                    return f'{val}{quantifier}'
                else:
                    return f'(?:{val}){quantifier}'
            elif kind == 'raw':
                val = target[1]
                return f'{val}{quantifier}'
            elif kind == 'symbol':
                sym_name = target[1]
                val = SYMBOLS[sym_name]
                return f'{val}{quantifier}'
            elif kind == 'not_symbol':
                sym_name = target[1]
                val = NOT_SYMBOLS[sym_name]
                return f'{val}{quantifier}'
            elif kind == 'not_range':
                start = target[1]
                end = target[2]
                return f'[^{start}-{end}]{quantifier}'
            elif kind == 'range':
                start = target[1]
                end = target[2]
                return f'[{start}-{end}]{quantifier}'
            elif kind == 'group_result':
                val = target[1]
                return f'{val}{quantifier}'
