                        t.get_source_line(error_line),
                        'amount or assertion_type')

    def parse_quantifier_or_range(self):
        """Parse either N of X or N to M of X or N to M (char range)."""
        t = self.tokenizer
        n = t.read_number()
        t.skip_whitespace_and_comments()

        # Check for 'of' - exact quantifier
        if t.source[t.pos:t.pos+2] == 'of' and (t.pos+2 >= len(t.source) or not (t.source[t.pos+2].isalnum() or t.source[t.pos+2] == '_')):
