        # Check for 'to'
        if t.source[t.pos:t.pos+2] == 'to' and (t.pos+2 >= len(t.source) or not (t.source[t.pos+2].isalnum() or t.source[t.pos+2] == '_')):
            for _ in 'to':
                t.advance()
            t.skip_whitespace_and_comments()

            # Read the next part
            if t.peek() and t.peek().isdigit():
                m = t.read_number()
