        raise ParseError(t.line, t.col, t.get_source_line(t.line), 'root')

    def parse_named_quantifier(self):
        """Parse some/any/option of X."""
        t = self.tokenizer

        if t.source[t.pos:t.pos+7] == 'some of':
            for _ in 'some of':
                t.advance()
            t.skip_whitespace_and_comments()
            target = self.parse_quantifier_target()
            return self.apply_quantifier(target, '+')

        if t.source[t.pos:t.pos+6] == 'any of':
            for _ in 'any of':
                t.advance()
            t.skip_whitespace_and_comments()
            target = self.parse_quantifier_target()
            return self.apply_quantifier(target, '*')

        if t.source[t.pos:t.pos+9] == 'option of':
            for _ in 'option of':
                t.advance()
            t.skip_whitespace_and_comments()
            target = self.parse_quantifier_target()
            return self.apply_quantifier(target, '?')

