    def parse_over_quantifier(self):
        """Parse: over N of X."""
        t = self.tokenizer
        for _ in 'over':
            t.advance()
        t.skip_whitespace_and_comments()
        n = t.read_number()
        t.skip_whitespace_and_comments()
        for _ in 'of':
            t.advance()
        t.skip_whitespace_and_comments()
        target = self.parse_quantifier_target()
        return self.apply_quantifier(target, f'{{{n+1},}}')

