                t.advance()
            t.skip_whitespace_and_comments()
            inner_ch = t.peek()

            if inner_ch == '<':
                sym_name = t.read_symbol()
                t.skip_whitespace_and_comments()
                t.expect_char(';')
                if sym_name not in SYMBOLS:
                    raise SemanticError("usage of an unrecognized symbol")
                if sym_name == 'char':
                    raise SemanticError("negative char not allowed")
                return ('not_symbol', sym_name)
            elif inner_ch and (inner_ch.isalpha() or inner_ch.isdigit()):
                start_char = t.advance()
                t.skip_whitespace_and_comments()
                if t.source[t.pos:t.pos+2] == 'to':
                    for _ in 'to':
                        t.advance()
                    t.skip_whitespace_and_comments()
                    end_char = t.advance()
                    t.skip_whitespace_and_comments()
                    t.expect_char(';')
                    return ('not_range', start_char, end_char)

