            saved_l = t.line
            saved_c = t.col
            start_char = t.advance()
            t.skip_whitespace_and_comments()
            if t.source[t.pos:t.pos+2] == 'to':
                for _ in 'to':
                    t.advance()
                t.skip_whitespace_and_comments()
                end_char = t.advance()
                t.skip_whitespace_and_comments()
                t.expect_char(';')
