        if t.source[t.pos:t.pos+5] == 'match':
            return ('group_result', self.parse_group('match'))
        if t.source[t.pos:t.pos+6] == 'either':
            return ('group_result', self.parse_group('either'))
        if t.source[t.pos:t.pos+7] == 'capture':
            return ('group_result', self.parse_capture())

        # Check for assertion
        if t.source[t.pos:t.pos+5] == 'ahead':
            return ('group_result', self.parse_assertion('ahead'))
        if t.source[t.pos:t.pos+6] == 'behind':
            return ('group_result', self.parse_assertion('behind'))

        raise ParseError(error_line, error_col, t.get_source_line(error_line),
                        'literal, raw, not, range, group_declaration, assertion_declaration, variable_declaration, or variable_invocation')

    def apply_quantifier(self, target, quantifier):
        """Apply a quantifier to a target."""
        if isinstance(target, tuple):
            kind = target[0]
            if kind == 'literal':
                val = target[1]
                if len(val) == 1 or (len(val) == 2 and val[0] == '\\'):
                    return f'{val}{quantifier}'
                else:
                    return f'(?:{val}){quantifier}'
            elif kind == 'raw':
                val = target[1]
                return f'{val}{quantifier}'
            elif kind == 'symbol':
                sym_name = target[1]
                val = SYMBOLS[sym_name]
                return f'{val}{quantifier}'
            elif kind == 'not_symbol':
                sym_name = target[1]
                val = NOT_SYMBOLS[sym_name]
                return f'{val}{quantifier}'
            elif kind == 'not_range':
                start = target[1]
                end = target[2]
                return f'[^{start}-{end}]{quantifier}'
            elif kind == 'range':
                start = target[1]
                end = target[2]
                return f'[{start}-{end}]{quantifier}'
            elif kind == 'group_result':
                val = target[1]
                return f'{val}{quantifier}'
        return f'{target}{quantifier}'

    def parse_group(self, kind):
        """Parse: match/either { ... }"""
        t = self.tokenizer
        for ch in kind:
            t.advance()
        t.skip_whitespace_and_comments()
        t.expect_char('{')
        inner = self.parse_block_contents()
        t.skip_whitespace_and_comments()
        t.expect_char('}')

        if kind == 'match':
            return f'(?:{inner})'
        elif kind == 'either':
            parts = self.split_either_parts(inner)
            return f'(?:{"|".join(parts)})'

    def split_either_parts(self, source):
