        # Actually, either's contents are compiled and pipe-separated
        # We need to parse each top-level statement of the inner block separately
        return [source]  # placeholder

    def parse_block_contents(self):
        """Parse the contents of a block { ... } and return compiled regex."""
        t = self.tokenizer
        result = []
        t.skip_whitespace_and_comments()

        while t.pos < len(t.source) and t.peek() != '}':
            stmt = self.parse_block_statement()
            result.append(stmt)
            t.skip_whitespace_and_comments()

        return ''.join(result)

    def parse_block_statement(self):
        """Parse a statement inside a block."""
        t = self.tokenizer
        t.skip_whitespace_and_comments()

        error_line = t.line
        error_col = t.col

        ch = t.peek()

        # Quantifiers
        if ch and ch.isdigit():
            return self.parse_quantifier_or_range()

        if ch == 's' and t.source[t.pos:t.pos+7] == 'some of':
            return self.parse_named_quantifier()
        if ch == 'a' and t.source[t.pos:t.pos+6] == 'any of':
            return self.parse_named_quantifier()
        if ch == 'o' and t.source[t.pos:t.pos+9] == 'option of':
            return self.parse_named_quantifier()
        if ch == 'o' and t.source[t.pos:t.pos+4] == 'over':
            return self.parse_over_quantifier()

        # Groups
        if t.source[t.pos:t.pos+5] == 'match':
            return self.parse_group('match')
        if t.source[t.pos:t.pos+6] == 'either':
            return self.parse_group('either')
        if t.source[t.pos:t.pos+7] == 'capture':
            return self.parse_capture()

        # Assertions
        if t.source[t.pos:t.pos+5] == 'ahead':
            return self.parse_assertion('ahead')
        if t.source[t.pos:t.pos+6] == 'behind':
            return self.parse_assertion('behind')

        if ch == 'n' and t.source[t.pos:t.pos+3] == 'not':
            return self.parse_not_statement()

