                        'quantifier_quantity, group_declaration, assertion_declaration, or variable_declaration')

    def parse_capture(self):
        """Parse: capture [name] { ... }"""
        t = self.tokenizer
        for _ in 'capture':
            t.advance()
        t.skip_whitespace_and_comments()

        # Check for optional name
        name = None
        if t.peek() != '{':
            # Read the name (identifier)
            name_line = t.line
            name_col = t.col
            ch = t.peek()
            if ch and (ch.isalpha() or ch == '_'):
                name = t.read_identifier()
                t.skip_whitespace_and_comments()
            else:
                raise ParseError(name_line, name_col,
                               t.get_source_line(name_line),
                               'block or identifier')

        t.expect_char('{')
        inner = self.parse_block_contents()
        t.skip_whitespace_and_comments()
        t.expect_char('}')

        if name:
            return f'(?<{name}>{inner})'
        else:
            return f'({inner})'

    def parse_assertion(self, kind):
        """Parse: ahead { ... } | behind { ... }"""
        t = self.tokenizer
        for ch in kind:
            t.advance()
        t.skip_whitespace_and_comments()
        t.expect_char('{')
        inner = self.parse_block_contents()
        t.skip_whitespace_and_comments()
        t.expect_char('}')

        if kind == 'ahead':
            return f'(?={inner})'
        elif kind == 'behind':
            return f'(?<={inner})'


