#!/usr/bin/env python3
"""Melody language compiler - compiles Melody to ECMAScript regex."""

import sys
import os
import re
import argparse

# ANSI color codes
COLOR_GREEN = '\033[92m'
COLOR_BLUE = '\033[94m'
COLOR_RED = '\033[91m'
COLOR_DIM = '\033[2m'
COLOR_RESET = '\033[39m'
COLOR_RESET_ALL = '\033[0m'

def use_color(no_color=False):
    """Return True if we should use color output."""
    if no_color:
        return False
    return sys.stdout.isatty()

def use_color_stderr(no_color=False):
    """Return True if we should use color for stderr."""
    if no_color:
        return False
    return sys.stderr.isatty()

def colorize(text, color, no_color=False, is_stderr=False):
    if is_stderr:
        should_color = use_color_stderr(no_color)
    else:
        should_color = use_color(no_color)
    if should_color:
        return f"{color}{text}{COLOR_RESET}"
    return text

# Special symbols mapping
SYMBOLS = {
    'char': '.',
    'space': ' ',
    'whitespace': r'\s',
    'digit': r'\d',
    'word': r'\w',
    'newline': r'\n',
    'tab': r'\t',
    'return': r'\r',
    'feed': r'\f',
    'null': r'\0',
    'vertical': r'\v',
    'backspace': r'[\b]',
    'boundary': r'\b',
    'start': '^',
    'end': '$',
    'alphanumeric': '[a-zA-Z0-9]',
}

NOT_SYMBOLS = {
    'char': None,  # Error
    'space': '[^ ]',
    'whitespace': r'\S',
    'digit': r'\D',
    'word': r'\W',
    'newline': r'[^\n]',
    'tab': r'[^\t]',
    'return': r'[^\r]',
    'feed': r'[^\f]',
    'null': r'[^\0]',
    'vertical': r'[^\v]',
    'backspace': r'[^\b]',
    'boundary': r'\B',
    'alphanumeric': '[^a-zA-Z0-9]',
}

SPECIAL_REGEX_CHARS = r'\.+*?[]{}()|^$/'

def escape_regex(s):
    """Escape special regex characters in a string."""
    result = []
    for ch in s:
        if ch in r'\.+*?[]{}()|^$':
            result.append('\\' + ch)
        else:
            result.append(ch)
    return ''.join(result)


class ParseError(Exception):
    def __init__(self, line, col, source_line, expected):
        self.line = line
        self.col = col
        self.source_line = source_line
        self.expected = expected

    def format(self, no_color=False):
        line_str = str(self.line)
        col_str = str(self.col)
        indent = ' ' * len(line_str)
        caret_indent = ' ' * (self.col - 1)
        msg = f"Error:  --> {line_str}:{col_str}\n"
        msg += f"{indent}  |\n"
        msg += f"{line_str} | {self.source_line}\n"
        msg += f"{indent}  | {caret_indent}^---\n"
        msg += f"{indent}  |\n"
        msg += f"{indent}  = expected {self.expected}"
        return msg


class SemanticError(Exception):
    def __init__(self, message):
        self.message = message

    def format(self):
        return f"Error: {self.message}"


class Tokenizer:
    """Tokenizes Melody source code."""

    def __init__(self, source):
        self.source = source
        self.pos = 0
        self.line = 1
        self.col = 1

    def get_source_line(self, line_num):
        """Get a specific source line (1-indexed)."""
        lines = self.source.split('\n')
        if 1 <= line_num <= len(lines):
            return lines[line_num - 1]
        return ''

    def peek(self):
        if self.pos < len(self.source):
            return self.source[self.pos]
        return None

    def advance(self):
        ch = self.source[self.pos]
        self.pos += 1
        if ch == '\n':
            self.line += 1
            self.col = 1
        else:
            self.col += 1
        return ch

    def skip_whitespace_and_comments(self):
        while self.pos < len(self.source):
            ch = self.peek()
            if ch in ' \t\r\n':
                self.advance()
            elif self.source[self.pos:self.pos+2] == '//':
                # Skip to end of line
                while self.pos < len(self.source) and self.peek() != '\n':
                    self.advance()
            else:
                break

    def read_string(self):
        """Read a double-quoted string literal."""
        start_line = self.line
        start_col = self.col
        assert self.advance() == '"'
        result = []
        while self.pos < len(self.source):
            ch = self.peek()
            if ch == '"':
                self.advance()
                return ''.join(result)
            elif ch == '\\':
                self.advance()
                if self.pos < len(self.source):
                    next_ch = self.advance()
                    if next_ch == '"':
                        result.append('"')
                    else:
                        result.append('\\')
                        result.append(next_ch)
                else:
                    result.append('\\')
            else:
                result.append(self.advance())
        # Unterminated string - this should cause a parse error
        raise ParseError(start_line, start_col, 
                        self.get_source_line(start_line), 'root')

    def read_raw(self):
        """Read a backtick-quoted raw regex."""
        start_line = self.line
        start_col = self.col
        assert self.advance() == '`'
        result = []
        while self.pos < len(self.source):
            ch = self.peek()
            if ch == '`':
                self.advance()
                return ''.join(result)
            elif ch == '\\':
                # Backslash not allowed in raw
                raise ParseError(start_line, start_col,
                                self.get_source_line(start_line), 'root')
            else:
                result.append(self.advance())
        raise ParseError(start_line, start_col,
                        self.get_source_line(start_line), 'root')

    def read_symbol(self):
        """Read <symbol>."""
        assert self.advance() == '<'
        name = []
        while self.pos < len(self.source) and self.peek() != '>':
            name.append(self.advance())
        if self.pos < len(self.source):
            self.advance()  # consume '>'
        return ''.join(name)

    def read_identifier(self):
        """Read an identifier (letters, digits, underscore)."""
        result = []
        while self.pos < len(self.source):
            ch = self.peek()
            if ch and (ch.isalnum() or ch == '_'):
                result.append(self.advance())
            else:
                break
        return ''.join(result)

    def read_number(self):
        """Read a number."""
        result = []
        while self.pos < len(self.source) and self.peek().isdigit():
            result.append(self.advance())
        return int(''.join(result))

    def expect_char(self, expected_char, expected_str=None):
        """Expect a specific character."""
        self.skip_whitespace_and_comments()
        if self.pos >= len(self.source) or self.peek() != expected_char:
            if expected_str is None:
                expected_str = f"'{expected_char}'"
            raise ParseError(self.line, self.col, 
                           self.get_source_line(self.line), expected_str)
        return self.advance()

    def expect_keyword(self, keyword, expected_str=None):
        """Expect a specific keyword."""
        self.skip_whitespace_and_comments()
        if self.source[self.pos:self.pos+len(keyword)] == keyword:
            # Check it's not part of a longer identifier
            end_pos = self.pos + len(keyword)
            if end_pos < len(self.source) and (self.source[end_pos].isalnum() or self.source[end_pos] == '_'):
                pass  # Not a keyword, part of identifier
            else:
                for _ in keyword:
                    self.advance()
                return True
        return False


class Parser:
    """Parses Melody source and compiles to regex."""

    def __init__(self, source):
        self.source = source
        self.tokenizer = Tokenizer(source)

    def parse(self):
        """Parse the full source and return regex string."""
        t = self.tokenizer
        result = []
        t.skip_whitespace_and_comments()

        while t.pos < len(t.source):
            t.skip_whitespace_and_comments()
            if t.pos >= len(t.source):
                break
            stmt = self.parse_root_statement()
            result.append(stmt)
            t.skip_whitespace_and_comments()

        return ''.join(result)

    def parse_root_statement(self):
        """Parse a top-level statement."""
        t = self.tokenizer
        t.skip_whitespace_and_comments()

        if t.pos >= len(t.source):
            raise ParseError(t.line, t.col, t.get_source_line(t.line), 'root')

        saved_pos = t.pos
        saved_line = t.line
        saved_col = t.col

        ch = t.peek()

        # Check for quantifier: number followed by 'of' or 'to'
        if ch and ch.isdigit():
            return self.parse_quantifier_or_range()

        # Check for 'some', 'any', 'option' quantifiers
        if ch == 's' and t.source[t.pos:t.pos+7] == 'some of':
            return self.parse_named_quantifier()
        if ch == 'a' and t.source[t.pos:t.pos+6] == 'any of':
            return self.parse_named_quantifier()
        if ch == 'o' and t.source[t.pos:t.pos+9] == 'option of':
            return self.parse_named_quantifier()
        if ch == 'o' and t.source[t.pos:t.pos+4] == 'over':
            return self.parse_over_quantifier()

        # Check for 'not'
        if ch == 'n' and t.source[t.pos:t.pos+3] == 'not':
            # Look ahead to determine not what
            saved_p = t.pos
            saved_l = t.line
            saved_c = t.col
            for _ in 'not':
                t.advance()
            t.skip_whitespace_and_comments()
            next_ch = t.peek()
            t.pos = saved_p
            t.line = saved_l
            t.col = saved_c

            # Could be: not <symbol>, not range, not ahead, not behind
            if next_ch == '<':
                return self.parse_not_symbol()
            elif next_ch and (next_ch.isalpha() or next_ch == '!'):
                # Check if next token is 'ahead', 'behind', or a range char
                return self.parse_not_statement()
            else:
                return self.parse_not_statement()

        # Check for group declarations
        if ch == 'm' and t.source[t.pos:t.pos+5] == 'match':
            return self.parse_group('match')
        if ch == 'e' and t.source[t.pos:t.pos+6] == 'either':
            return self.parse_group('either')
        if ch == 'c' and t.source[t.pos:t.pos+7] == 'capture':
            return self.parse_capture()

        # Check for assertion declarations
        if ch == 'a' and t.source[t.pos:t.pos+5] == 'ahead':
            return self.parse_assertion('ahead')
        if ch == 'b' and t.source[t.pos:t.pos+6] == 'behind':
            return self.parse_assertion('behind')

        # Check for literals
        if ch == '"':
            return self.parse_literal_stmt()

        # Check for raw regex
        if ch == '`':
            return self.parse_raw_stmt()

        # Check for range (single char to single char)
        if ch and ch.isalpha() and self.is_range_start():
            return self.parse_range_stmt()

        raise ParseError(t.line, t.col, t.get_source_line(t.line), 
                        'root')

    def is_range_start(self):
        """Check if current position starts a character range."""
        t = self.tokenizer
        saved_pos = t.pos
        saved_line = t.line
        saved_col = t.col

        # Try to read: char whitespace 'to' whitespace char ';'
        try:
            ch = t.peek()
            if not ch or not (ch.isalpha() or ch.isdigit() or ch in '!-~'):
                return False
            t.advance()
            t.skip_whitespace_and_comments()
            if t.source[t.pos:t.pos+2] != 'to':
                t.pos = saved_pos
                t.line = saved_line
                t.col = saved_col
                return False
            t.pos = saved_pos
            t.line = saved_line
            t.col = saved_col
            return True
        except:
            t.pos = saved_pos
            t.line = saved_line
            t.col = saved_col
            return False

    def parse_range_stmt(self):
        """Parse: char to char;"""
        t = self.tokenizer
        start_char = t.advance()
        t.skip_whitespace_and_comments()
        # consume 'to'
        for ch in 'to':
            t.advance()
        t.skip_whitespace_and_comments()
        end_char = t.advance()
        t.skip_whitespace_and_comments()
        t.expect_char(';')
        return f'[{start_char}-{end_char}]'

    def parse_literal_stmt(self):
        """Parse: "string";"""
        t = self.tokenizer
        s = t.read_string()
        t.skip_whitespace_and_comments()
        t.expect_char(';')
        return escape_regex(s)

    def parse_raw_stmt(self):
        """Parse: `regex`;"""
        t = self.tokenizer
        r = t.read_raw()
        t.skip_whitespace_and_comments()
        t.expect_char(';')
        return r

    def parse_not_symbol(self):
        """Parse: not <symbol>;"""
        t = self.tokenizer
        for _ in 'not':
            t.advance()
        t.skip_whitespace_and_comments()
        sym_name = t.read_symbol()
        t.skip_whitespace_and_comments()
        t.expect_char(';')

        if sym_name not in SYMBOLS and sym_name not in NOT_SYMBOLS:
            raise SemanticError("usage of an unrecognized symbol")

        if sym_name == 'char':
            raise SemanticError("negative char not allowed")
        if sym_name == 'start' or sym_name == 'end':
            raise SemanticError("negative char not allowed")

        if sym_name in NOT_SYMBOLS:
            return NOT_SYMBOLS[sym_name]
        raise SemanticError(f"usage of an unrecognized symbol")

    def parse_not_statement(self):
        """Parse: not <symbol>; | not range; | not ahead {...} | not behind {...}"""
        t = self.tokenizer
        error_line = t.line
        error_col = t.col

        for _ in 'not':
            t.advance()
        t.skip_whitespace_and_comments()

        ch = t.peek()

        # Check for 'ahead' or 'behind'
        if t.source[t.pos:t.pos+5] == 'ahead':
            for _ in 'ahead':
                t.advance()
            t.skip_whitespace_and_comments()
            t.expect_char('{')
            inner = self.parse_block_contents()
            t.expect_char('}')
            return f'(?!{inner})'

        if t.source[t.pos:t.pos+6] == 'behind':
            for _ in 'behind':
                t.advance()
            t.skip_whitespace_and_comments()
            t.expect_char('{')
            inner = self.parse_block_contents()
            t.expect_char('}')
            return f'(?<!{inner})'

        # Check for symbol
        if ch == '<':
            sym_name = t.read_symbol()
            t.skip_whitespace_and_comments()
            t.expect_char(';')

            if sym_name not in SYMBOLS:
                raise SemanticError("usage of an unrecognized symbol")

            if sym_name == 'char':
                raise SemanticError("negative char not allowed")
            if sym_name == 'start' or sym_name == 'end':
                raise SemanticError("negative char not allowed")

            if sym_name in NOT_SYMBOLS:
                return NOT_SYMBOLS[sym_name]
            raise SemanticError("usage of an unrecognized symbol")

        # Check for range: char to char
        if ch and (ch.isalpha() or ch.isdigit()):
            start_char = t.advance()
            t.skip_whitespace_and_comments()
            if t.source[t.pos:t.pos+2] == 'to':
                for _ in 'to':
                    t.advance()
                t.skip_whitespace_and_comments()
                end_char = t.advance()
                t.skip_whitespace_and_comments()
                t.expect_char(';')
                return f'[^{start_char}-{end_char}]'

        raise ParseError(error_line, error_col,
                        t.get_source_line(error_line),
                        'amount or assertion_type')

    def parse_quantifier_or_range(self):
        """Parse either N of X or N to M of X or N to M (char range)."""
        t = self.tokenizer
        n = t.read_number()
        t.skip_whitespace_and_comments()

        # Check for 'of' - exact quantifier
        if t.source[t.pos:t.pos+2] == 'of' and (t.pos+2 >= len(t.source) or not (t.source[t.pos+2].isalnum() or t.source[t.pos+2] == '_')):
            for _ in 'of':
                t.advance()
            t.skip_whitespace_and_comments()
            target = self.parse_quantifier_target()
            return self.apply_quantifier(target, f'{{{n}}}')

        # Check for 'to'
        if t.source[t.pos:t.pos+2] == 'to' and (t.pos+2 >= len(t.source) or not (t.source[t.pos+2].isalnum() or t.source[t.pos+2] == '_')):
            for _ in 'to':
                t.advance()
            t.skip_whitespace_and_comments()

            # Read the next part
            if t.peek() and t.peek().isdigit():
                m = t.read_number()
                t.skip_whitespace_and_comments()

                # Check for 'of' - range quantifier
                if t.source[t.pos:t.pos+2] == 'of' and (t.pos+2 >= len(t.source) or not (t.source[t.pos+2].isalnum() or t.source[t.pos+2] == '_')):
                    for _ in 'of':
                        t.advance()
                    t.skip_whitespace_and_comments()
                    target = self.parse_quantifier_target()
                    return self.apply_quantifier(target, f'{{{n},{m}}}')

                # It's a char range: n to m
                t.expect_char(';')
                return f'[{n}-{m}]'

            # Char range: N to single_char
            end_char = t.advance()
            t.skip_whitespace_and_comments()
            t.expect_char(';')
            return f'[{n}-{end_char}]'

        # Just a number on its own - error
        raise ParseError(t.line, t.col, t.get_source_line(t.line), 'root')

    def parse_named_quantifier(self):
        """Parse some/any/option of X."""
        t = self.tokenizer

        if t.source[t.pos:t.pos+7] == 'some of':
            for _ in 'some of':
                t.advance()
            t.skip_whitespace_and_comments()
            target = self.parse_quantifier_target()
            return self.apply_quantifier(target, '+')

        if t.source[t.pos:t.pos+6] == 'any of':
            for _ in 'any of':
                t.advance()
            t.skip_whitespace_and_comments()
            target = self.parse_quantifier_target()
            return self.apply_quantifier(target, '*')

        if t.source[t.pos:t.pos+9] == 'option of':
            for _ in 'option of':
                t.advance()
            t.skip_whitespace_and_comments()
            target = self.parse_quantifier_target()
            return self.apply_quantifier(target, '?')

        raise ParseError(t.line, t.col, t.get_source_line(t.line), 'root')

    def parse_over_quantifier(self):
        """Parse: over N of X."""
        t = self.tokenizer
        for _ in 'over':
            t.advance()
        t.skip_whitespace_and_comments()
        n = t.read_number()
        t.skip_whitespace_and_comments()
        for _ in 'of':
            t.advance()
        t.skip_whitespace_and_comments()
        target = self.parse_quantifier_target()
        return self.apply_quantifier(target, f'{{{n+1},}}')

    def parse_quantifier_target(self):
        """Parse what comes after 'of' - can be literal, raw, symbol, range, or group."""
        t = self.tokenizer
        t.skip_whitespace_and_comments()

        error_line = t.line
        error_col = t.col

        ch = t.peek()

        if ch == '"':
            s = t.read_string()
            t.skip_whitespace_and_comments()
            t.expect_char(';')
            return ('literal', escape_regex(s))

        if ch == '`':
            r = t.read_raw()
            t.skip_whitespace_and_comments()
            t.expect_char(';')
            return ('raw', r)

        if ch == '<':
            sym_name = t.read_symbol()
            t.skip_whitespace_and_comments()
            t.expect_char(';')
            if sym_name not in SYMBOLS:
                raise SemanticError("usage of an unrecognized symbol")
            return ('symbol', sym_name)

        if ch == 'n' and t.source[t.pos:t.pos+3] == 'not':
            # not symbol or not range
            for _ in 'not':
                t.advance()
            t.skip_whitespace_and_comments()
            inner_ch = t.peek()

            if inner_ch == '<':
                sym_name = t.read_symbol()
                t.skip_whitespace_and_comments()
                t.expect_char(';')
                if sym_name not in SYMBOLS:
                    raise SemanticError("usage of an unrecognized symbol")
                if sym_name == 'char':
                    raise SemanticError("negative char not allowed")
                return ('not_symbol', sym_name)
            elif inner_ch and (inner_ch.isalpha() or inner_ch.isdigit()):
                start_char = t.advance()
                t.skip_whitespace_and_comments()
                if t.source[t.pos:t.pos+2] == 'to':
                    for _ in 'to':
                        t.advance()
                    t.skip_whitespace_and_comments()
                    end_char = t.advance()
                    t.skip_whitespace_and_comments()
                    t.expect_char(';')
                    return ('not_range', start_char, end_char)

        # Check for range: char to char
        if ch and (ch.isalpha() or ch.isdigit() or ch in '!-~'):
            saved_p = t.pos
            saved_l = t.line
            saved_c = t.col
            start_char = t.advance()
            t.skip_whitespace_and_comments()
            if t.source[t.pos:t.pos+2] == 'to':
                for _ in 'to':
                    t.advance()
                t.skip_whitespace_and_comments()
                end_char = t.advance()
                t.skip_whitespace_and_comments()
                t.expect_char(';')
                return ('range', start_char, end_char)
            t.pos = saved_p
            t.line = saved_l
            t.col = saved_c

        # Check for group declarations
        if t.source[t.pos:t.pos+5] == 'match':
            return ('group_result', self.parse_group('match'))
        if t.source[t.pos:t.pos+6] == 'either':
            return ('group_result', self.parse_group('either'))
        if t.source[t.pos:t.pos+7] == 'capture':
            return ('group_result', self.parse_capture())

        # Check for assertion
        if t.source[t.pos:t.pos+5] == 'ahead':
            return ('group_result', self.parse_assertion('ahead'))
        if t.source[t.pos:t.pos+6] == 'behind':
            return ('group_result', self.parse_assertion('behind'))

        raise ParseError(error_line, error_col, t.get_source_line(error_line),
                        'literal, raw, not, range, group_declaration, assertion_declaration, variable_declaration, or variable_invocation')

    def apply_quantifier(self, target, quantifier):
        """Apply a quantifier to a target."""
        if isinstance(target, tuple):
            kind = target[0]
            if kind == 'literal':
                val = target[1]
                if len(val) == 1 or (len(val) == 2 and val[0] == '\\'):
                    return f'{val}{quantifier}'
                else:
                    return f'(?:{val}){quantifier}'
            elif kind == 'raw':
                val = target[1]
                return f'{val}{quantifier}'
            elif kind == 'symbol':
                sym_name = target[1]
                val = SYMBOLS[sym_name]
                return f'{val}{quantifier}'
            elif kind == 'not_symbol':
                sym_name = target[1]
                val = NOT_SYMBOLS[sym_name]
                return f'{val}{quantifier}'
            elif kind == 'not_range':
                start = target[1]
                end = target[2]
                return f'[^{start}-{end}]{quantifier}'
            elif kind == 'range':
                start = target[1]
                end = target[2]
                return f'[{start}-{end}]{quantifier}'
            elif kind == 'group_result':
                val = target[1]
                return f'{val}{quantifier}'
        return f'{target}{quantifier}'

    def parse_group(self, kind):
        """Parse: match/either { ... }"""
        t = self.tokenizer
        for ch in kind:
            t.advance()
        t.skip_whitespace_and_comments()
        t.expect_char('{')
        inner = self.parse_block_contents()
        t.skip_whitespace_and_comments()
        t.expect_char('}')

        if kind == 'match':
            return f'(?:{inner})'
        elif kind == 'either':
            parts = self.split_either_parts(inner)
            return f'(?:{"|".join(parts)})'

    def split_either_parts(self, source):
        """This doesn't work as-is, need to handle differently."""
        # Actually, either's contents are compiled and pipe-separated
        # We need to parse each top-level statement of the inner block separately
        return [source]  # placeholder

    def parse_block_contents(self):
        """Parse the contents of a block { ... } and return compiled regex."""
        t = self.tokenizer
        result = []
        t.skip_whitespace_and_comments()

        while t.pos < len(t.source) and t.peek() != '}':
            stmt = self.parse_block_statement()
            result.append(stmt)
            t.skip_whitespace_and_comments()

        return ''.join(result)

    def parse_block_statement(self):
        """Parse a statement inside a block."""
        t = self.tokenizer
        t.skip_whitespace_and_comments()

        error_line = t.line
        error_col = t.col

        ch = t.peek()

        # Quantifiers
        if ch and ch.isdigit():
            return self.parse_quantifier_or_range()

        if ch == 's' and t.source[t.pos:t.pos+7] == 'some of':
            return self.parse_named_quantifier()
        if ch == 'a' and t.source[t.pos:t.pos+6] == 'any of':
            return self.parse_named_quantifier()
        if ch == 'o' and t.source[t.pos:t.pos+9] == 'option of':
            return self.parse_named_quantifier()
        if ch == 'o' and t.source[t.pos:t.pos+4] == 'over':
            return self.parse_over_quantifier()

        # Groups
        if t.source[t.pos:t.pos+5] == 'match':
            return self.parse_group('match')
        if t.source[t.pos:t.pos+6] == 'either':
            return self.parse_group('either')
        if t.source[t.pos:t.pos+7] == 'capture':
            return self.parse_capture()

        # Assertions
        if t.source[t.pos:t.pos+5] == 'ahead':
            return self.parse_assertion('ahead')
        if t.source[t.pos:t.pos+6] == 'behind':
            return self.parse_assertion('behind')

        if ch == 'n' and t.source[t.pos:t.pos+3] == 'not':
            return self.parse_not_statement()

        if ch == '"':
            return self.parse_literal_stmt()

        if ch == '`':
            return self.parse_raw_stmt()

        # Range
        if ch and (ch.isalpha() or ch.isdigit()):
            if self.is_range_start():
                return self.parse_range_stmt()

        raise ParseError(error_line, error_col, t.get_source_line(error_line),
                        'quantifier_quantity, group_declaration, assertion_declaration, or variable_declaration')

    def parse_capture(self):
        """Parse: capture [name] { ... }"""
        t = self.tokenizer
        for _ in 'capture':
