#!/usr/bin/env python3
"""Melody language compiler - compiles Melody to ECMAScript regex."""

import sys
import os
import re
import argparse

# ANSI color codes
COLOR_GREEN = '\033[92m'
COLOR_BLUE = '\033[94m'
COLOR_RED = '\033[91m'
COLOR_DIM = '\033[2m'
COLOR_RESET = '\033[39m'
COLOR_RESET_ALL = '\033[0m'

def use_color(no_color=False):
