# Special symbols mapping
SYMBOLS = {
    'char': '.',
    'space': ' ',
    'whitespace': r'\s',
    'digit': r'\d',
    'word': r'\w',
    'newline': r'\n',
    'tab': r'\t',
    'return': r'\r',
    'feed': r'\f',
    'null': r'\0',
    'vertical': r'\v',
    'backspace': r'[\b]',
    'boundary': r'\b',
    'start': '^',
    'end': '$',
    'alphanumeric': '[a-zA-Z0-9]',
}

NOT_SYMBOLS = {
    'char': None,  # Error
    'space': '[^ ]',
    'whitespace': r'\S',
    'digit': r'\D',
    'word': r'\W',
    'newline': r'[^\n]',
    'tab': r'[^\t]',
    'return': r'[^\r]',
    'feed': r'[^\f]',
    'null': r'[^\0]',
    'vertical': r'[^\v]',
    'backspace': r'[^\b]',
    'boundary': r'\B',
