class ParseError(Exception):
    def __init__(self, line, col, source_line, expected):
        self.line = line
        self.col = col
        self.source_line = source_line
        self.expected = expected

    def format(self, no_color=False):
        line_str = str(self.line)
        col_str = str(self.col)
        indent = ' ' * len(line_str)
        caret_indent = ' ' * (self.col - 1)
        msg = f"Error:  --> {line_str}:{col_str}\n"
        msg += f"{indent}  |\n"
        msg += f"{line_str} | {self.source_line}\n"
        msg += f"{indent}  | {caret_indent}^---\n"
        msg += f"{indent}  |\n"
        msg += f"{indent}  = expected {self.expected}"
        return msg


