    def __init__(self, message):
        self.message = message

    def format(self):
        return f"Error: {self.message}"


class Tokenizer:
    """Tokenizes Melody source code."""

    def __init__(self, source):
        self.source = source
        self.pos = 0
        self.line = 1
        self.col = 1

    def get_source_line(self, line_num):
        """Get a specific source line (1-indexed)."""
        lines = self.source.split('\n')
        if 1 <= line_num <= len(lines):
            return lines[line_num - 1]
        return ''

    def peek(self):
        if self.pos < len(self.source):
            return self.source[self.pos]
        return None

    def advance(self):
        ch = self.source[self.pos]
        self.pos += 1
        if ch == '\n':
            self.line += 1
            self.col = 1
        else:
            self.col += 1
        return ch

    def skip_whitespace_and_comments(self):
        while self.pos < len(self.source):
            ch = self.peek()
            if ch in ' \t\r\n':
                self.advance()
            elif self.source[self.pos:self.pos+2] == '//':
                # Skip to end of line
                while self.pos < len(self.source) and self.peek() != '\n':
                    self.advance()
            else:
                break

    def read_string(self):
        """Read a double-quoted string literal."""
        start_line = self.line
        start_col = self.col
        assert self.advance() == '"'
        result = []
        while self.pos < len(self.source):
            ch = self.peek()
            if ch == '"':
                self.advance()
                return ''.join(result)
            elif ch == '\\':
                self.advance()
                if self.pos < len(self.source):
                    next_ch = self.advance()
                    if next_ch == '"':
                        result.append('"')
                    else:
                        result.append('\\')
                        result.append(next_ch)
                else:
                    result.append('\\')
            else:
                result.append(self.advance())
        # Unterminated string - this should cause a parse error
        raise ParseError(start_line, start_col, 
                        self.get_source_line(start_line), 'root')

    def read_raw(self):
        """Read a backtick-quoted raw regex."""
        start_line = self.line
        start_col = self.col
        assert self.advance() == '`'
        result = []
        while self.pos < len(self.source):
            ch = self.peek()
            if ch == '`':
                self.advance()
                return ''.join(result)
            elif ch == '\\':
                # Backslash not allowed in raw
                raise ParseError(start_line, start_col,
                                self.get_source_line(start_line), 'root')
            else:
                result.append(self.advance())
        raise ParseError(start_line, start_col,
                        self.get_source_line(start_line), 'root')

    def read_symbol(self):
        """Read <symbol>."""
        assert self.advance() == '<'
        name = []
        while self.pos < len(self.source) and self.peek() != '>':
            name.append(self.advance())
        if self.pos < len(self.source):
            self.advance()  # consume '>'
        return ''.join(name)

    def read_identifier(self):
        """Read an identifier (letters, digits, underscore)."""
        result = []
        while self.pos < len(self.source):
            ch = self.peek()
            if ch and (ch.isalnum() or ch == '_'):
                result.append(self.advance())
            else:
                break
