    def read_number(self):
        """Read a number."""
        result = []
        while self.pos < len(self.source) and self.peek().isdigit():
            result.append(self.advance())
        return int(''.join(result))

    def expect_char(self, expected_char, expected_str=None):
        """Expect a specific character."""
        self.skip_whitespace_and_comments()
        if self.pos >= len(self.source) or self.peek() != expected_char:
            if expected_str is None:
                expected_str = f"'{expected_char}'"
            raise ParseError(self.line, self.col, 
                           self.get_source_line(self.line), expected_str)
        return self.advance()

    def expect_keyword(self, keyword, expected_str=None):
        """Expect a specific keyword."""
        self.skip_whitespace_and_comments()
        if self.source[self.pos:self.pos+len(keyword)] == keyword:
            # Check it's not part of a longer identifier
            end_pos = self.pos + len(keyword)
            if end_pos < len(self.source) and (self.source[end_pos].isalnum() or self.source[end_pos] == '_'):
                pass  # Not a keyword, part of identifier
            else:
                for _ in keyword:
                    self.advance()
                return True
        return False


