#!/usr/bin/env python3
"""Melody language compiler - converts Melody to ECMAScript regex."""

import sys
import os
import re
import argparse
import readline
import io

VERSION = "0.20.0"

# ANSI color codes
class Color:
    GREEN = '\033[92m'
    BLUE = '\033[94m'
    RED = '\033[91m'
    DIM = '\033[2m'
    RESET = '\033[39m'
    RESET_ALL = '\033[0m'

def supports_color(stream):
    """Check if stream supports color output."""
    return hasattr(stream, 'isatty') and stream.isatty()

def colorize(text, color, stream=None, no_color=False):
    if no_color:
        return text
    if stream is None:
