    """Read "..." string. src should be at the opening quote."""
    assert src.peek() == '"'
    start_line = src.line
    start_col = src.col
    src.advance()  # consume "
    result = []
    while not src.eof():
        ch = src.peek()
        if ch == '"':
            src.advance()
            return ''.join(result)
        elif ch == '\\':
            src.advance()
            if src.eof():
                result.append('\\')
