    """Read `...` raw regex. src should be at the opening backtick."""
    assert src.peek() == '`'
    start_line = src.line
    start_col = src.col
    src.advance()  # consume `
    result = []
    while not src.eof():
        ch = src.peek()
        if ch == '`':
            src.advance()
            return ''.join(result)
        elif ch == '\\':
