            raise SemanticError("usage of an unrecognized symbol")
        return SYMBOLS[sym]

    if read_keyword_peek(src, 'not'):
        return parse_not_for_quantifier(src)

    # Char range
    if ch and (ch.isalpha() or ch.isdigit() or ch in '!-~'):
        state = src.save()
        start_ch = src.advance()
        src.skip_ws_comments()
        if read_keyword(src, 'to'):
            src.skip_ws_comments()
            if not src.eof() and (src.peek().isalpha() or src.peek().isdigit() or src.peek() in '!-~'):
                end_ch = src.advance()
                src.skip_ws_comments()
                expect_char(src, ';')
                return f'[{start_ch}-{end_ch}]'
        src.restore(state)

    # Groups
    if read_keyword_peek(src, 'match'):
        return parse_match(src)
    if read_keyword_peek(src, 'either'):
        return parse_either(src)
    if read_keyword_peek(src, 'capture'):
        return parse_capture(src)
    if read_keyword_peek(src, 'ahead'):
        return parse_ahead(src, negative=False)
    if read_keyword_peek(src, 'behind'):
        return parse_behind(src, negative=False)

    raise ParseError(line, col, line_text,
                    'literal, raw, not, range, group_declaration, assertion_declaration, variable_declaration, or variable_invocation')


def parse_not_for_quantifier(src):
    """Parse 'not X' as quantifier target, returns raw regex string."""
    # Consume 'not'
    for _ in 'not':
        src.advance()
    src.skip_ws_comments()
    line, col, line_text = src.current_pos_info()
    ch = src.peek()

    if ch == '<':
        sym = read_symbol(src)
        expect_semicolon(src)
        if sym not in SYMBOLS:
            raise SemanticError("usage of an unrecognized symbol")
        if sym == 'char':
            raise SemanticError("negative char not allowed")
        if sym == 'start':
            raise SemanticError("negative start not allowed")
        if sym == 'end':
            raise SemanticError("negative end not allowed")
        if sym in NOT_SYMBOLS and NOT_SYMBOLS[sym] is not None:
            return NOT_SYMBOLS[sym]
        raise SemanticError("usage of an unrecognized symbol")

    # Char range: not char to char
    if ch and (ch.isalpha() or ch.isdigit()):
        state = src.save()
        start_ch = src.advance()
        src.skip_ws_comments()
        if read_keyword(src, 'to'):
            src.skip_ws_comments()
            end_ch = src.advance()
            src.skip_ws_comments()
            expect_char(src, ';')
            return f'[^{start_ch}-{end_ch}]'
        src.restore(state)

    raise ParseError(line, col, line_text, 'amount or assertion_type')


def parse_not(src):
    """Parse 'not ...' statement."""
    # Consume 'not'
    for _ in 'not':
        src.advance()
    src.skip_ws_comments()
    line, col, line_text = src.current_pos_info()
    ch = src.peek()

    # not ahead { ... }
    if read_keyword_peek(src, 'ahead'):
        return parse_ahead(src, negative=True)

    # not behind { ... }
    if read_keyword_peek(src, 'behind'):
        return parse_behind(src, negative=True)

    # not <symbol>;
    if ch == '<':
        sym = read_symbol(src)
        expect_semicolon(src)
        if sym not in SYMBOLS:
            raise SemanticError("usage of an unrecognized symbol")
        if sym == 'char':
            raise SemanticError("negative char not allowed")
        if sym == 'start':
            raise SemanticError("negative start not allowed")
        if sym == 'end':
            raise SemanticError("negative end not allowed")
        if sym in NOT_SYMBOLS and NOT_SYMBOLS[sym] is not None:
            return NOT_SYMBOLS[sym]
        raise SemanticError("usage of an unrecognized symbol")

    # not char to char; (char range negation)
    if ch and (ch.isalpha() or ch.isdigit()):
        state = src.save()
        start_ch = src.advance()
        src.skip_ws_comments()
        if read_keyword(src, 'to'):
            src.skip_ws_comments()
            if not src.eof():
                end_ch = src.advance()
                src.skip_ws_comments()
                expect_char(src, ';')
                return f'[^{start_ch}-{end_ch}]'
        src.restore(state)

    raise ParseError(line, col, line_text, 'amount or assertion_type')


def parse_numeric(src):
    """Parse numeric statement: N of X, N to M of X, or N to M (char range)."""
    n = read_number(src)
    src.skip_ws_comments()
    line, col, line_text = src.current_pos_info()

    # Check for 'of' (exact quantifier: N of X)
    if read_keyword(src, 'of'):
        src.skip_ws_comments()
        target = parse_quantifier_target(src)
        return apply_quantifier(target, f'{{{n}}}')

    # Check for 'to' (range or range quantifier)
    if read_keyword(src, 'to'):
        src.skip_ws_comments()
        # Next could be a number (for quantifier range N to M of X)
        # or a single char (for char range)
        if not src.eof() and src.peek().isdigit():
            m = read_number(src)
            src.skip_ws_comments()
            # Check for 'of'
            if read_keyword(src, 'of'):
                src.skip_ws_comments()
                target = parse_quantifier_target(src)
                return apply_quantifier(target, f'{{{n},{m}}}')
            # Otherwise it's a char range: n to m
            expect_char(src, ';')
            return f'[{n}-{m}]'
        else:
            # Single char range: n to char
            if src.eof():
                raise ParseError(line, col, line_text, 'root')
            end_ch = src.advance()
            src.skip_ws_comments()
            expect_char(src, ';')
            return f'[{n}-{end_ch}]'

    raise ParseError(line, col, line_text, 'root')


def parse_quantifier_with_keyword(src, keyword, quantifier_char):
    """Parse 'some of X', 'any of X', 'option of X'."""
    for ch in keyword:
        src.advance()
    src.skip_ws_comments()
    target = parse_quantifier_target(src)
    return apply_quantifier(target, quantifier_char)


def parse_over(src):
    """Parse 'over N of X'."""
    read_keyword(src, 'over')
    src.skip_ws_comments()
    n = read_number(src)
    if n is None:
        raise src.parse_error('root')
    src.skip_ws_comments()
    if not read_keyword(src, 'of'):
        raise src.parse_error('root')
    src.skip_ws_comments()
    target = parse_quantifier_target(src)
    return apply_quantifier(target, f'{{{n+1},}}')


def parse_block_contents(src):
    """Parse contents of { ... } block, returning list of compiled parts."""
    parts = []
    src.skip_ws_comments()
    while not src.eof() and src.peek() != '}':
        part = parse_statement(src, in_block=True)
        parts.append(part)
        src.skip_ws_comments()
    return parts


def parse_match(src):
    """Parse 'match { ... }'."""
    read_keyword(src, 'match')
    src.skip_ws_comments()
    expect_char(src, '{')
    parts = parse_block_contents(src)
    src.skip_ws_comments()
    expect_char(src, '}')
    inner = ''.join(parts)
    return f'(?:{inner})'


def parse_either(src):
    """Parse 'either { ... }'."""
    read_keyword(src, 'either')
    src.skip_ws_comments()
    expect_char(src, '{')
    parts = parse_block_contents(src)
    src.skip_ws_comments()
    expect_char(src, '}')
    return '(?:' + '|'.join(parts) + ')'


def parse_capture(src):
    """Parse 'capture [name] { ... }'."""
    read_keyword(src, 'capture')
    src.skip_ws_comments()
    line, col, line_text = src.current_pos_info()
    ch = src.peek()

    name_parts = []
    if ch != '{':
        # Read the name: one or more identifiers separated by spaces
        # Identifier = [a-zA-Z_]+
        # We need to collect text until we hit '{'
        first_ident = read_identifier(src)
        if first_ident is None:
            raise ParseError(line, col, line_text, 'block or identifier')
        name_parts.append(first_ident)

        while True:
            state = src.save()
            src.skip_ws_comments()
            if src.eof() or src.peek() == '{':
                break
            # Try to read another identifier
            ch2 = src.peek()
            if ch2 and is_identifier_char(ch2):
                ident = read_identifier(src)
                name_parts.append(ident)
            else:
                # Something unexpected
                raise src.parse_error('block')

    src.skip_ws_comments()
    expect_char(src, '{')
    parts = parse_block_contents(src)
    src.skip_ws_comments()
    expect_char(src, '}')
    inner = ''.join(parts)

    if name_parts:
        # The name preserves whitespace between parts
        # Based on observation: "capture first second" -> "(?<first second>...)"
        # And "capture   abc   def" -> "(?<abc  def>...)" - trailing spaces after 'capture' trimmed
        # Let me reconstruct with single space between parts for now
        # Actually: reconstruct from the raw source
        name = ' '.join(name_parts)
        return f'(?<{name}>{inner})'
    else:
        return f'({inner})'


def parse_ahead(src, negative=False):
    """Parse 'ahead { ... }' or 'not ahead { ... }'."""
    read_keyword(src, 'ahead')
    src.skip_ws_comments()
    expect_char(src, '{')
    parts = parse_block_contents(src)
    src.skip_ws_comments()
    expect_char(src, '}')
    inner = ''.join(parts)
    if negative:
        return f'(?!{inner})'
    return f'(?={inner})'


def parse_behind(src, negative=False):
    """Parse 'behind { ... }' or 'not behind { ... }'."""
    read_keyword(src, 'behind')
    src.skip_ws_comments()
    expect_char(src, '{')
    parts = parse_block_contents(src)
    src.skip_ws_comments()
    expect_char(src, '}')
    inner = ''.join(parts)
    if negative:
        return f'(?<!{inner})'
    return f'(?<={inner})'


# ===== CLI Implementation =====

COMPLETIONS_BASH = '''_melody() {
    local i cur prev opts cmd
    COMPREPLY=()
    cur="${COMP_WORDS[COMP_CWORD]}"
    prev="${COMP_WORDS[COMP_CWORD-1]}"
    cmd=""
    opts=""

    for i in ${COMP_WORDS[@]}
    do
        case "${cmd},${i}" in
            ",$1")
                cmd="melody"
                ;;
            *)
                ;;
        esac
    done

    case "${cmd}" in
        melody)
            opts="-o -n -r -t -f -h -V --output --no-color --repl --generate-completions --test --test-file --help --version [INPUT_FILE_PATH]"
            if [[ ${cur} == -* || ${COMP_CWORD} -eq 1 ]] ; then
                COMPREPLY=( $(compgen -W "${opts}" -- "${cur}") )
                return 0
            fi
            case "${prev}" in
                --output)
                    COMPREPLY=($(compgen -f "${cur}"))
                    return 0
                    ;;
                -o)
                    COMPREPLY=($(compgen -f "${cur}"))
                    return 0
                    ;;
                --generate-completions)
                    COMPREPLY=($(compgen -W "bash elvish fish powershell zsh" -- "${cur}"))
                    return 0
                    ;;
                --test)
                    COMPREPLY=($(compgen -f "${cur}"))
                    return 0
                    ;;
                -t)
                    COMPREPLY=($(compgen -f "${cur}"))
                    return 0
                    ;;
                --test-file)
                    COMPREPLY=($(compgen -f "${cur}"))
                    return 0
                    ;;
                -f)
                    COMPREPLY=($(compgen -f "${cur}"))
                    return 0
                    ;;
                *)
                    COMPREPLY=()
                    return 0
                    ;;
            esac
            ;;
    esac
}

complete -F _melody -o bashdefault -o default melody
'''

def get_completions(shell):
    # These are pre-generated completion scripts
    if shell == 'bash':
        return COMPLETIONS_BASH
    # For other shells, return empty for now
    return ''


def truncate_test_string(s, max_len=10):
    """Truncate a string for display in test output."""
    if len(s) > max_len:
        return s[:max_len] + '...'
    return s


def run_test(regex_str, test_str, no_color=False):
    """Test regex against a string and print result."""
    pattern = re.compile(regex_str)
    display = truncate_test_string(test_str)
    if pattern.search(test_str):
        matched = colorize('matched', Color.GREEN, sys.stdout, no_color)
        print(f"'{display}' {matched}")
    else:
        not_matched = colorize('did not match', Color.RED, sys.stdout, no_color)
        print(f"'{display}' {not_matched}")


def run_test_file(regex_str, file_path, no_color=False):
    """Test regex against a file's contents."""
    try:
        with open(file_path, 'r') as f:
            content = f.read()
    except (IOError, OSError):
        print(f"Error: unable read file at path {file_path}", file=sys.stderr)
        return

    pattern = re.compile(regex_str)
    if pattern.search(content):
        matched = colorize('matched', Color.GREEN, sys.stdout, no_color)
        print(f"{file_path} {matched}")
    else:
        not_matched = colorize('did not match', Color.RED, sys.stdout, no_color)
        print(f"{file_path} {not_matched}")


def print_error(msg, no_color=False):
    """Print an error message to stderr."""
    colored = colorize(msg, Color.RED, sys.stderr, no_color)
    print(colored, file=sys.stderr)


def print_regex(regex_str, no_color=False, output_file=None):
    """Print or write the compiled regex."""
    if output_file:
        with open(output_file, 'w') as f:
            f.write(regex_str)
    else:
        colored = colorize(regex_str, Color.BLUE, sys.stdout, no_color)
        print(colored)


def run_repl(no_color=False):
    """Run the interactive REPL."""
    # Check if stdin/stdout is a TTY
    if not sys.stdin.isatty() or not sys.stdout.isatty():
        print(colorize("Error: repl argument supplied with piped input or output", 
                       Color.RED, sys.stderr, no_color), file=sys.stderr)
        return

    lines = []
    undo_stack = []  # stack of (lines, redo_stack) for undo
    redo_stack = []  # list of removed lines

    def print_colored(text, color=Color.GREEN):
        print(colorize(text, color, sys.stdout, no_color))

    def print_prompt():
        sys.stdout.write(colorize('~ ', Color.BLUE, sys.stdout, no_color))
        sys.stdout.flush()

    # Print welcome banner
    print_colored(f"Melody REPL v{VERSION}")
    print()
    print_colored("Commands:")
    print()
    print(f"- {colorize(':u, :undo', Color.BLUE, sys.stdout, no_color)} - {colorize('undo the latest line', Color.GREEN, sys.stdout, no_color)}")
    print(f"- {colorize(':r, :redo', Color.BLUE, sys.stdout, no_color)} - {colorize('redo the latest undo', Color.GREEN, sys.stdout, no_color)}")
    print(f"- {colorize(':c, :clear', Color.BLUE, sys.stdout, no_color)} - {colorize('clear all REPL history and previous input', Color.GREEN, sys.stdout, no_color)}")
    print(f"- {colorize(':s, :source', Color.BLUE, sys.stdout, no_color)} - {colorize('print all previously entered lines', Color.GREEN, sys.stdout, no_color)}")
    print(f"- {colorize(':e, :exit', Color.BLUE, sys.stdout, no_color)} - {colorize('exit the REPL', Color.GREEN, sys.stdout, no_color)}")
    print()

    while True:
        print_prompt()
        try:
            line = input()
        except EOFError:
            break
        except KeyboardInterrupt:
            print()
            break

        cmd = line.strip()

        if cmd in (':e', ':exit'):
            print_colored('exit')
            break
        elif cmd in (':u', ':undo'):
            print_colored('undo')
            if lines:
                removed = lines.pop()
                redo_stack.append(removed)
            else:
                print_colored('nothing to undo')
                continue
            # Recompile and show result
            if lines:
                try:
                    source = '\n'.join(lines)
                    regex = compile_source(source)
                    print(colorize(regex, Color.BLUE, sys.stdout, no_color))
                except (ParseError, SemanticError) as e:
                    print(colorize(e.format(), Color.RED, sys.stdout, no_color))
        elif cmd in (':r', ':redo'):
            print_colored('redo')
            if redo_stack:
                restored = redo_stack.pop()
                lines.append(restored)
                # Recompile and show result
                try:
                    source = '\n'.join(lines)
                    regex = compile_source(source)
                    print(colorize(regex, Color.BLUE, sys.stdout, no_color))
                except (ParseError, SemanticError) as e:
                    print(colorize(e.format(), Color.RED, sys.stdout, no_color))
            else:
                print_colored('nothing to redo')
        elif cmd in (':c', ':clear'):
            print_colored('clear')
            lines = []
            redo_stack = []
        elif cmd in (':s', ':source'):
            print_colored('source')
            for i, l in enumerate(lines, 1):
                num = colorize_dim(str(i), sys.stdout, no_color)
                code = colorize(l, Color.BLUE, sys.stdout, no_color)
                print(f"{num} {code}")
        elif cmd.startswith(':'):
            print(colorize(f'Error: unrecognized command "{cmd}"', Color.RED, sys.stdout, no_color))
        else:
            # Try to compile
            new_lines = lines + [line]
            source = '\n'.join(new_lines)
            try:
                regex = compile_source(source)
                lines = new_lines
                redo_stack = []  # clear redo on new input
                print(colorize(regex, Color.BLUE, sys.stdout, no_color))
            except ParseError as e:
                print(colorize(e.format(), Color.RED, sys.stdout, no_color))
            except SemanticError as e:
                print(colorize(e.format(), Color.RED, sys.stdout, no_color))


def main():
    parser = argparse.ArgumentParser(
        prog='melody',
        description='A CLI wrapping the Melody language compiler',
        add_help=False,
    )
    parser.add_argument('input_file', nargs='?', metavar='INPUT_FILE_PATH',
                       help="Read from a file\nUse '-' and or pipe input to read from stdin")
    parser.add_argument('-o', '--output', metavar='OUTPUT_FILE_PATH',
                       help='Write to a file')
    parser.add_argument('-n', '--no-color', action='store_true',
                       help='Print output with no color')
    parser.add_argument('-r', '--repl', action='store_true',
                       help='Start the Melody REPL')
    parser.add_argument('--generate-completions', metavar='completions',
                       help='Outputs completions for the selected shell\nTo use, write the output to the appropriate location for your shell')
    parser.add_argument('-t', '--test', metavar='test',
                       help='Test the compiled regex against a string')
    parser.add_argument('-f', '--test-file', metavar='test-file',
                       help='Test the compiled regex against the contents of a file')
    parser.add_argument('-h', '--help', action='store_true',
                       help='Print help')
    parser.add_argument('-V', '--version', action='store_true',
                       help='Print version')

    args = parser.parse_args()

    no_color = args.no_color

    if args.help:
        print("""A CLI wrapping the Melody language compiler

Usage: melody [OPTIONS] [INPUT_FILE_PATH]

Arguments:
  [INPUT_FILE_PATH]  Read from a file
                     Use '-' and or pipe input to read from stdin

Options:
  -o, --output <OUTPUT_FILE_PATH>           Write to a file
  -n, --no-color                            Print output with no color
  -r, --repl                                Start the Melody REPL
      --generate-completions <completions>  Outputs completions for the selected shell
                                            To use, write the output to the appropriate location for your shell
  -t, --test <test>                         Test the compiled regex against a string
  -f, --test-file <test-file>               Test the compiled regex against the contents of a file
  -h, --help                                Print help
  -V, --version                             Print version""")
        return

    if args.version:
        print(f"melody_cli {VERSION}")
        return

    if args.generate_completions:
        completions = get_completions(args.generate_completions)
        print(completions, end='')
        return

    if args.repl:
        run_repl(no_color=no_color)
        return

    # Read input
    source = None
    if args.input_file:
        if args.input_file == '-':
            source = sys.stdin.read()
        else:
            try:
                with open(args.input_file, 'r') as f:
                    source = f.read()
            except (IOError, OSError):
                print_error(f"Error: unable to read file at path {args.input_file}", no_color)
                sys.exit(65)
    elif not sys.stdin.isatty():
        source = sys.stdin.read()
    else:
        parser.print_help()
        return

    if source is None:
        return

    # Compile
    try:
        regex = compile_source(source)
    except ParseError as e:
        print_error(e.format(), no_color)
        sys.exit(65)
    except SemanticError as e:
        print_error(e.format(), no_color)
        sys.exit(65)

    # Handle test
    if args.test is not None:
        run_test(regex, args.test, no_color)
        return

    if args.test_file is not None:
        run_test_file(regex, args.test_file, no_color)
        return

    # Output regex
    print_regex(regex, no_color, args.output)


if __name__ == '__main__':
    main()
