VERSION = "0.20.0"

# ANSI color codes
class Color:
    GREEN = '\033[92m'
    BLUE = '\033[94m'
    RED = '\033[91m'
    DIM = '\033[2m'
    RESET = '\033[39m'
    RESET_ALL = '\033[0m'

def supports_color(stream):
