    'space': ' ',
    'whitespace': r'\s',
    'digit': r'\d',
    'word': r'\w',
    'newline': r'\n',
    'tab': r'\t',
    'return': r'\r',
    'feed': r'\f',
    'null': r'\0',
    'vertical': r'\v',
    'backspace': r'[\b]',
    'boundary': r'\b',
    'start': '^',
    'end': '$',
    'alphanumeric': '[a-zA-Z0-9]',
}

NOT_SYMBOLS = {
    'char': None,  # Error: negative char not allowed
    'space': '[^ ]',
    'whitespace': r'\S',
    'digit': r'\D',
    'word': r'\W',
    'newline': r'[^\n]',
    'tab': r'[^\t]',
    'return': r'[^\r]',
    'feed': r'[^\f]',
    'null': r'[^\0]',
    'vertical': r'[^\v]',
    'backspace': r'[^\b]',
    'boundary': r'\B',
    'alphanumeric': '[^a-zA-Z0-9]',
    'start': None,  # Error: negative start not allowed
    'end': None,    # Error: negative end not allowed
}

REGEX_SPECIAL = set(r'\.+*?[]{}()|^$')

def escape_regex(s):
    """Escape special regex characters in a string literal."""
    result = []
    for ch in s:
        if ch in REGEX_SPECIAL:
            result.append('\\' + ch)
        else:
            result.append(ch)
    return ''.join(result)

def is_single_atom(s):
    """Return True if s is a single regex atom (doesn't need grouping for quantification)."""
    if len(s) == 1:
        return True
    # \x (two chars: backslash + one char)
    if len(s) == 2 and s[0] == '\\':
        return True
    # [class] forms
    if s.startswith('[') and s.endswith(']'):
        return True
    # existing groups (?:...) or (...) etc
    if s.startswith('(') and s.endswith(')'):
        return True
    return False


class ParseError(Exception):
    def __init__(self, line, col, source_line, expected):
        self.line = line
        self.col = col
        self.source_line = source_line
        self.expected = expected

    def format(self):
        line_s = str(self.line)
        indent = ' ' * len(line_s)
        caret = ' ' * (self.col - 1)
        lines = [
            f"Error:  --> {line_s}:{self.col}",
            f"{indent}  |",
            f"{line_s} | {self.source_line}",
            f"{indent}  | {caret}^---",
            f"{indent}  |",
            f"{indent}  = expected {self.expected}",
        ]
        return '\n'.join(lines)


class SemanticError(Exception):
    def __init__(self, message):
        self.message = message

    def format(self):
        return f"Error: {self.message}"


class Source:
    """Tracks position in source text."""

    def __init__(self, text):
        self.text = text
        self.pos = 0
        self.line = 1
        self.col = 1

    def get_line_text(self, line_num):
        lines = self.text.split('\n')
        if 1 <= line_num <= len(lines):
            return lines[line_num - 1]
        return ''

    def eof(self):
        return self.pos >= len(self.text)

    def peek(self, offset=0):
        p = self.pos + offset
        if p < len(self.text):
            return self.text[p]
        return None

    def peek_str(self, n):
        return self.text[self.pos:self.pos + n]

    def advance(self):
        if self.pos >= len(self.text):
            return None
        ch = self.text[self.pos]
        self.pos += 1
        if ch == '\n':
            self.line += 1
            self.col = 1
        else:
            self.col += 1
        return ch

    def save(self):
        return (self.pos, self.line, self.col)

    def restore(self, state):
        self.pos, self.line, self.col = state

    def skip_ws_comments(self):
        while not self.eof():
            ch = self.peek()
            if ch in ' \t\r\n':
                self.advance()
            elif self.peek_str(2) == '//':
                while not self.eof() and self.peek() != '\n':
                    self.advance()
            else:
                break

    def current_pos_info(self):
        return (self.line, self.col, self.get_line_text(self.line))

    def parse_error(self, expected):
        return ParseError(self.line, self.col, self.get_line_text(self.line), expected)


def is_identifier_char(ch):
    return ch.isalpha() or ch == '_'


def read_identifier(src):
    """Read [a-zA-Z_]+ identifier."""
    result = []
    while not src.eof() and is_identifier_char(src.peek()):
        result.append(src.advance())
    if not result:
        return None
    return ''.join(result)


def read_number(src):
    """Read integer."""
    if src.eof() or not src.peek().isdigit():
        return None
    result = []
    while not src.eof() and src.peek().isdigit():
        result.append(src.advance())
    return int(''.join(result))


def read_keyword(src, kw):
    """Try to read a keyword (not followed by identifier char)."""
    n = len(kw)
    if src.peek_str(n) != kw:
        return False
    # Check boundary
    if src.pos + n < len(src.text):
        next_ch = src.text[src.pos + n]
        if is_identifier_char(next_ch) or next_ch.isdigit():
            return False
    for _ in kw:
        src.advance()
    return True


def read_string(src):
    """Read "..." string. src should be at the opening quote."""
    assert src.peek() == '"'
    start_line = src.line
    start_col = src.col
    src.advance()  # consume "
    result = []
    while not src.eof():
        ch = src.peek()
        if ch == '"':
            src.advance()
            return ''.join(result)
        elif ch == '\\':
            src.advance()
            if src.eof():
                result.append('\\')
                break
            next_ch = src.advance()
            if next_ch == '"':
                result.append('"')
            else:
                result.append('\\')
                result.append(next_ch)
        else:
            result.append(src.advance())
    # Unterminated - parse error at start of string
    raise ParseError(start_line, start_col, src.get_line_text(start_line), 'root')


def read_raw(src):
    """Read `...` raw regex. src should be at the opening backtick."""
    assert src.peek() == '`'
    start_line = src.line
    start_col = src.col
    src.advance()  # consume `
    result = []
    while not src.eof():
        ch = src.peek()
        if ch == '`':
            src.advance()
            return ''.join(result)
        elif ch == '\\':
            # Backslash not allowed in raw
            raise ParseError(start_line, start_col, src.get_line_text(start_line), 'root')
        else:
            result.append(src.advance())
    raise ParseError(start_line, start_col, src.get_line_text(start_line), 'root')


def read_symbol(src):
    """Read <symbolname>. src should be at '<'."""
    assert src.peek() == '<'
    src.advance()  # consume <
    name = []
    while not src.eof() and src.peek() != '>':
        name.append(src.advance())
    if not src.eof():
        src.advance()  # consume >
    return ''.join(name)


def expect_char(src, ch, expected=None):
    src.skip_ws_comments()
    if src.eof() or src.peek() != ch:
        if expected is None:
            expected = f"'{ch}'"
        raise src.parse_error(expected)
    src.advance()


def expect_semicolon(src, expected=None):
    src.skip_ws_comments()
    if src.eof() or src.peek() != ';':
        if expected is None:
            expected = "EOI, literal, raw, not, range, quantifier_quantity, group_declaration, assertion_declaration, variable_declaration, or variable_invocation"
        raise src.parse_error(expected)
    src.advance()


def apply_quantifier(regex, quantifier):
    """Apply quantifier to regex, adding (?:...) if needed."""
    if is_single_atom(regex):
        return regex + quantifier
    else:
        return f'(?:{regex}){quantifier}'


# ===== Main compilation functions =====

def compile_source(source_text):
    """Compile Melody source to regex string."""
    src = Source(source_text)
    parts = []
    src.skip_ws_comments()
    while not src.eof():
        part = parse_statement(src, in_block=False)
        parts.append(part)
        src.skip_ws_comments()
    return ''.join(parts)


def parse_statement(src, in_block=False):
    """Parse a single statement at top level or inside a block."""
    src.skip_ws_comments()

    if src.eof():
        if in_block:
            raise src.parse_error('quantifier_quantity, group_declaration, assertion_declaration, or variable_declaration')
        raise src.parse_error('root')

    line, col, line_text = src.current_pos_info()
    ch = src.peek()

    # --- Quantifiers with numbers ---
    if ch and ch.isdigit():
        return parse_numeric(src)

    # --- Named quantifiers ---
    if read_keyword_peek(src, 'some of'):
        return parse_quantifier_with_keyword(src, 'some of', '+')

    if read_keyword_peek(src, 'any of'):
        return parse_quantifier_with_keyword(src, 'any of', '*')

    if read_keyword_peek(src, 'option of'):
        return parse_quantifier_with_keyword(src, 'option of', '?')

    if read_keyword_peek(src, 'over'):
        return parse_over(src)

    # --- 'not' ---
    if read_keyword_peek(src, 'not'):
        return parse_not(src)

    # --- Groups ---
    if read_keyword_peek(src, 'match'):
        return parse_match(src)

    if read_keyword_peek(src, 'either'):
        return parse_either(src)

    if read_keyword_peek(src, 'capture'):
        return parse_capture(src)

    # --- Assertions ---
    if read_keyword_peek(src, 'ahead'):
        return parse_ahead(src, negative=False)

    if read_keyword_peek(src, 'behind'):
        return parse_behind(src, negative=False)

    # --- Literals ---
    if ch == '"':
        s = read_string(src)
        expect_semicolon(src)
        return escape_regex(s)

    # --- Raw regex ---
    if ch == '`':
        r = read_raw(src)
        expect_semicolon(src)
        return r

    # --- Symbols ---
    if ch == '<':
        sym = read_symbol(src)
        expect_semicolon(src)
        if sym not in SYMBOLS:
            raise SemanticError("usage of an unrecognized symbol")
        return SYMBOLS[sym]

    # --- Char ranges: char to char ---
    if ch and (ch.isalpha() or ch.isdigit() or ch in '!-~'):
        state = src.save()
        start_ch = src.advance()
        src.skip_ws_comments()
        if read_keyword(src, 'to'):
            src.skip_ws_comments()
            if not src.eof() and (src.peek().isalpha() or src.peek().isdigit() or src.peek() in '!-~'):
                end_ch = src.advance()
                src.skip_ws_comments()
                expect_char(src, ';')
                return f'[{start_ch}-{end_ch}]'
        # Not a range, restore
        src.restore(state)

    if in_block:
        raise ParseError(line, col, line_text, 
                        'quantifier_quantity, group_declaration, assertion_declaration, or variable_declaration')
    raise ParseError(line, col, line_text, 'root')


def read_keyword_peek(src, kw):
    """Check (without consuming) if current position has keyword kw."""
    n = len(kw)
    if src.peek_str(n) != kw:
        return False
    # Check the character AFTER the keyword
    pos_after = src.pos + n
    if pos_after < len(src.text):
        next_ch = src.text[pos_after]
        # For multi-word keywords like "some of", the boundary check is on the last word
        # We just check if it's an exact match as a prefix
        # Actually for "some of" we need to verify the 'of' part too
        # Let me just check if there's a non-ident char after kw
        last_ch = kw[-1]
        if last_ch.isalpha() or last_ch == '_':
            if is_identifier_char(next_ch) or next_ch.isdigit():
                return False
    return True


def parse_quantifier_target(src):
    """Parse what comes after 'of' in a quantifier context."""
    src.skip_ws_comments()
    line, col, line_text = src.current_pos_info()
    ch = src.peek()

    if ch == '"':
        s = read_string(src)
        expect_semicolon(src)
        return escape_regex(s)

    if ch == '`':
        r = read_raw(src)
        expect_semicolon(src)
        return r

    if ch == '<':
        sym = read_symbol(src)
        expect_semicolon(src)
        if sym not in SYMBOLS:
            raise SemanticError("usage of an unrecognized symbol")
        return SYMBOLS[sym]

    if read_keyword_peek(src, 'not'):
        return parse_not_for_quantifier(src)

    # Char range
    if ch and (ch.isalpha() or ch.isdigit() or ch in '!-~'):
        state = src.save()
        start_ch = src.advance()
        src.skip_ws_comments()
        if read_keyword(src, 'to'):
            src.skip_ws_comments()
            if not src.eof() and (src.peek().isalpha() or src.peek().isdigit() or src.peek() in '!-~'):
                end_ch = src.advance()
                src.skip_ws_comments()
                expect_char(src, ';')
                return f'[{start_ch}-{end_ch}]'
        src.restore(state)

    # Groups
    if read_keyword_peek(src, 'match'):
        return parse_match(src)
    if read_keyword_peek(src, 'either'):
        return parse_either(src)
    if read_keyword_peek(src, 'capture'):
        return parse_capture(src)
    if read_keyword_peek(src, 'ahead'):
        return parse_ahead(src, negative=False)
    if read_keyword_peek(src, 'behind'):
        return parse_behind(src, negative=False)

    raise ParseError(line, col, line_text,
                    'literal, raw, not, range, group_declaration, assertion_declaration, variable_declaration, or variable_invocation')


def parse_not_for_quantifier(src):
    """Parse 'not X' as quantifier target, returns raw regex string."""
    # Consume 'not'
    for _ in 'not':
        src.advance()
    src.skip_ws_comments()
    line, col, line_text = src.current_pos_info()
    ch = src.peek()

    if ch == '<':
        sym = read_symbol(src)
        expect_semicolon(src)
        if sym not in SYMBOLS:
            raise SemanticError("usage of an unrecognized symbol")
        if sym == 'char':
            raise SemanticError("negative char not allowed")
        if sym == 'start':
            raise SemanticError("negative start not allowed")
        if sym == 'end':
            raise SemanticError("negative end not allowed")
        if sym in NOT_SYMBOLS and NOT_SYMBOLS[sym] is not None:
            return NOT_SYMBOLS[sym]
        raise SemanticError("usage of an unrecognized symbol")

    # Char range: not char to char
    if ch and (ch.isalpha() or ch.isdigit()):
        state = src.save()
        start_ch = src.advance()
        src.skip_ws_comments()
        if read_keyword(src, 'to'):
            src.skip_ws_comments()
            end_ch = src.advance()
            src.skip_ws_comments()
            expect_char(src, ';')
            return f'[^{start_ch}-{end_ch}]'
        src.restore(state)

    raise ParseError(line, col, line_text, 'amount or assertion_type')


def parse_not(src):
    """Parse 'not ...' statement."""
    # Consume 'not'
    for _ in 'not':
        src.advance()
    src.skip_ws_comments()
    line, col, line_text = src.current_pos_info()
    ch = src.peek()

    # not ahead { ... }
    if read_keyword_peek(src, 'ahead'):
        return parse_ahead(src, negative=True)

    # not behind { ... }
    if read_keyword_peek(src, 'behind'):
        return parse_behind(src, negative=True)

    # not <symbol>;
    if ch == '<':
        sym = read_symbol(src)
        expect_semicolon(src)
        if sym not in SYMBOLS:
            raise SemanticError("usage of an unrecognized symbol")
        if sym == 'char':
            raise SemanticError("negative char not allowed")
        if sym == 'start':
            raise SemanticError("negative start not allowed")
        if sym == 'end':
            raise SemanticError("negative end not allowed")
        if sym in NOT_SYMBOLS and NOT_SYMBOLS[sym] is not None:
            return NOT_SYMBOLS[sym]
        raise SemanticError("usage of an unrecognized symbol")

    # not char to char; (char range negation)
    if ch and (ch.isalpha() or ch.isdigit()):
        state = src.save()
        start_ch = src.advance()
        src.skip_ws_comments()
        if read_keyword(src, 'to'):
            src.skip_ws_comments()
            if not src.eof():
                end_ch = src.advance()
                src.skip_ws_comments()
                expect_char(src, ';')
                return f'[^{start_ch}-{end_ch}]'
        src.restore(state)

    raise ParseError(line, col, line_text, 'amount or assertion_type')


def parse_numeric(src):
    """Parse numeric statement: N of X, N to M of X, or N to M (char range)."""
    n = read_number(src)
    src.skip_ws_comments()
    line, col, line_text = src.current_pos_info()

    # Check for 'of' (exact quantifier: N of X)
    if read_keyword(src, 'of'):
        src.skip_ws_comments()
        target = parse_quantifier_target(src)
        return apply_quantifier(target, f'{{{n}}}')

    # Check for 'to' (range or range quantifier)
    if read_keyword(src, 'to'):
        src.skip_ws_comments()
        # Next could be a number (for quantifier range N to M of X)
        # or a single char (for char range)
        if not src.eof() and src.peek().isdigit():
            m = read_number(src)
            src.skip_ws_comments()
            # Check for 'of'
            if read_keyword(src, 'of'):
                src.skip_ws_comments()
                target = parse_quantifier_target(src)
                return apply_quantifier(target, f'{{{n},{m}}}')
            # Otherwise it's a char range: n to m
            expect_char(src, ';')
            return f'[{n}-{m}]'
        else:
            # Single char range: n to char
            if src.eof():
                raise ParseError(line, col, line_text, 'root')
            end_ch = src.advance()
            src.skip_ws_comments()
            expect_char(src, ';')
            return f'[{n}-{end_ch}]'

    raise ParseError(line, col, line_text, 'root')


def parse_quantifier_with_keyword(src, keyword, quantifier_char):
    """Parse 'some of X', 'any of X', 'option of X'."""
    for ch in keyword:
        src.advance()
    src.skip_ws_comments()
    target = parse_quantifier_target(src)
    return apply_quantifier(target, quantifier_char)


def parse_over(src):
    """Parse 'over N of X'."""
    read_keyword(src, 'over')
    src.skip_ws_comments()
    n = read_number(src)
    if n is None:
        raise src.parse_error('root')
    src.skip_ws_comments()
    if not read_keyword(src, 'of'):
        raise src.parse_error('root')
    src.skip_ws_comments()
    target = parse_quantifier_target(src)
    return apply_quantifier(target, f'{{{n+1},}}')


def parse_block_contents(src):
    """Parse contents of { ... } block, returning list of compiled parts."""
    parts = []
    src.skip_ws_comments()
    while not src.eof() and src.peek() != '}':
        part = parse_statement(src, in_block=True)
        parts.append(part)
        src.skip_ws_comments()
    return parts


def parse_match(src):
    """Parse 'match { ... }'."""
    read_keyword(src, 'match')
    src.skip_ws_comments()
    expect_char(src, '{')
    parts = parse_block_contents(src)
    src.skip_ws_comments()
    expect_char(src, '}')
    inner = ''.join(parts)
    return f'(?:{inner})'


def parse_either(src):
    """Parse 'either { ... }'."""
    read_keyword(src, 'either')
    src.skip_ws_comments()
    expect_char(src, '{')
    parts = parse_block_contents(src)
    src.skip_ws_comments()
    expect_char(src, '}')
    return '(?:' + '|'.join(parts) + ')'


def parse_capture(src):
    """Parse 'capture [name] { ... }'."""
    read_keyword(src, 'capture')
    src.skip_ws_comments()
    line, col, line_text = src.current_pos_info()
    ch = src.peek()

    name_parts = []
    if ch != '{':
        # Read the name: one or more identifiers separated by spaces
        # Identifier = [a-zA-Z_]+
        # We need to collect text until we hit '{'
        first_ident = read_identifier(src)
        if first_ident is None:
            raise ParseError(line, col, line_text, 'block or identifier')
        name_parts.append(first_ident)

        while True:
            state = src.save()
            src.skip_ws_comments()
            if src.eof() or src.peek() == '{':
                break
            # Try to read another identifier
            ch2 = src.peek()
            if ch2 and is_identifier_char(ch2):
                ident = read_identifier(src)
                name_parts.append(ident)
            else:
                # Something unexpected
                raise src.parse_error('block')

    src.skip_ws_comments()
    expect_char(src, '{')
    parts = parse_block_contents(src)
    src.skip_ws_comments()
    expect_char(src, '}')
    inner = ''.join(parts)

    if name_parts:
        # The name preserves whitespace between parts
        # Based on observation: "capture first second" -> "(?<first second>...)"
        # And "capture   abc   def" -> "(?<abc  def>...)" - trailing spaces after 'capture' trimmed
        # Let me reconstruct with single space between parts for now
        # Actually: reconstruct from the raw source
        name = ' '.join(name_parts)
        return f'(?<{name}>{inner})'
    else:
        return f'({inner})'


def parse_ahead(src, negative=False):
    """Parse 'ahead { ... }' or 'not ahead { ... }'."""
    read_keyword(src, 'ahead')
    src.skip_ws_comments()
    expect_char(src, '{')
    parts = parse_block_contents(src)
    src.skip_ws_comments()
    expect_char(src, '}')
    inner = ''.join(parts)
    if negative:
        return f'(?!{inner})'
    return f'(?={inner})'


def parse_behind(src, negative=False):
    """Parse 'behind { ... }' or 'not behind { ... }'."""
    read_keyword(src, 'behind')
    src.skip_ws_comments()
    expect_char(src, '{')
    parts = parse_block_contents(src)
    src.skip_ws_comments()
    expect_char(src, '}')
    inner = ''.join(parts)
    if negative:
        return f'(?<!{inner})'
    return f'(?<={inner})'


