def parse_quantifier_target(src):
    """Parse what comes after 'of' in a quantifier context."""
    src.skip_ws_comments()
    line, col, line_text = src.current_pos_info()
    ch = src.peek()

    if ch == '"':
        s = read_string(src)
        expect_semicolon(src)
        return escape_regex(s)

    if ch == '`':
        r = read_raw(src)
        expect_semicolon(src)
        return r

    if ch == '<':
        sym = read_symbol(src)
        expect_semicolon(src)
        if sym not in SYMBOLS:
            raise SemanticError("usage of an unrecognized symbol")
        return SYMBOLS[sym]

    if read_keyword_peek(src, 'not'):
        return parse_not_for_quantifier(src)

    # Char range
    if ch and (ch.isalpha() or ch.isdigit() or ch in '!-~'):
        state = src.save()
        start_ch = src.advance()
        src.skip_ws_comments()
        if read_keyword(src, 'to'):
            src.skip_ws_comments()
            if not src.eof() and (src.peek().isalpha() or src.peek().isdigit() or src.peek() in '!-~'):
                end_ch = src.advance()
                src.skip_ws_comments()
                expect_char(src, ';')
                return f'[{start_ch}-{end_ch}]'
        src.restore(state)

    # Groups
    if read_keyword_peek(src, 'match'):
        return parse_match(src)
    if read_keyword_peek(src, 'either'):
        return parse_either(src)
    if read_keyword_peek(src, 'capture'):
        return parse_capture(src)
    if read_keyword_peek(src, 'ahead'):
        return parse_ahead(src, negative=False)
    if read_keyword_peek(src, 'behind'):
        return parse_behind(src, negative=False)

    raise ParseError(line, col, line_text,
                    'literal, raw, not, range, group_declaration, assertion_declaration, variable_declaration, or variable_invocation')


def parse_not_for_quantifier(src):
    """Parse 'not X' as quantifier target, returns raw regex string."""
    # Consume 'not'
    for _ in 'not':
        src.advance()
    src.skip_ws_comments()
    line, col, line_text = src.current_pos_info()
    ch = src.peek()

    if ch == '<':
        sym = read_symbol(src)
        expect_semicolon(src)
        if sym not in SYMBOLS:
            raise SemanticError("usage of an unrecognized symbol")
        if sym == 'char':
            raise SemanticError("negative char not allowed")
        if sym == 'start':
            raise SemanticError("negative start not allowed")
        if sym == 'end':
            raise SemanticError("negative end not allowed")
