#!/usr/bin/env python3
"""Melody language compiler - converts Melody to ECMAScript regex."""

import sys
import os
import re
import argparse

VERSION = "0.20.0"

# ANSI color codes
class Color:
    GREEN = '\033[92m'
    BLUE = '\033[94m'
    RED = '\033[91m'
    DIM = '\033[2m'
    RESET = '\033[39m'
    RESET_ALL = '\033[0m'

def _has_color(stream):
    return hasattr(stream, 'isatty') and stream.isatty()

def colorize(text, color, stream, no_color=False):
    if no_color or not _has_color(stream):
        return text
    return f"{color}{text}{Color.RESET}"

def colorize_dim(text, stream, no_color=False):
    if no_color or not _has_color(stream):
        return text
    return f"{Color.DIM}{text}{Color.RESET_ALL}"

# Symbol tables
SYMBOLS = {
    'char': '.',
    'space': ' ',
    'whitespace': r'\s',
    'digit': r'\d',
    'word': r'\w',
    'newline': r'\n',
    'tab': r'\t',
    'return': r'\r',
    'feed': r'\f',
    'null': r'\0',
    'vertical': r'\v',
    'backspace': r'[\b]',
    'boundary': r'\b',
    'start': '^',
    'end': '$',
    'alphanumeric': '[a-zA-Z0-9]',
}

NOT_SYMBOLS = {
    'space': '[^ ]',
    'whitespace': r'\S',
    'digit': r'\D',
    'word': r'\W',
    'newline': r'[^\n]',
    'tab': r'[^\t]',
    'return': r'[^\r]',
    'feed': r'[^\f]',
    'null': r'[^\0]',
    'vertical': r'[^\v]',
    'backspace': r'[^\b]',
    'boundary': r'\B',
    'alphanumeric': '[^a-zA-Z0-9]',
}

NOT_ERRORS = {
    'char': 'negative char not allowed',
    'start': 'negative start not allowed',
    'end': 'negative end not allowed',
}

REGEX_SPECIAL = frozenset(r'\.+*?[]{}()|^$')

def escape_regex(s):
    result = []
    for ch in s:
        if ch in REGEX_SPECIAL:
            result.append('\\' + ch)
        else:
            result.append(ch)
    return ''.join(result)

def is_single_atom(s):
    """Return True if regex s is a single atom (doesn't need grouping for quantifiers)."""
    if not s:
        return True
    # Single character (no special meaning)
    if len(s) == 1:
        return s not in '+*?|.^$'
    # Escape sequence: \X
    if len(s) == 2 and s[0] == '\\':
        return True
    # Character class: [...]
    if s[0] == '[' and s[-1] == ']':
        return True
    # Any group: (...) - could be (?:...), (?=...), etc.
    if s[0] == '(' and s[-1] == ')':
        # We need to count parens to make sure it's a single complete group
        depth = 0
        for i, ch in enumerate(s):
            if ch == '(':
                depth += 1
            elif ch == ')':
                depth -= 1
            if depth == 0 and i < len(s) - 1:
                return False  # Multiple groups
        return True
    return False

def apply_quantifier(inner_regex, quantifier):
    """Apply quantifier to inner_regex, adding (?:...) if needed."""
    if is_single_atom(inner_regex):
        return inner_regex + quantifier
    return f'(?:{inner_regex}){quantifier}'


class ParseError(Exception):
    def __init__(self, line, col, source_line, expected):
        self.line = line
        self.col = col
        self.source_line = source_line
        self.expected = expected

    def format(self):
        line_s = str(self.line)
        # The indent is a fixed alignment based on the line number width
        # "Error: " has 7 chars, and we add len(line_s) spaces before "-->"
        # so total prefix before "-->" is 7 + len(line_s) chars
        # The "|" lines use indent = len(line_s) + 1 spaces
        indent = ' ' * (len(line_s) + 1)
        caret = ' ' * (self.col - 1)
        return '\n'.join([
            f"Error: {' ' * len(line_s)}--> {line_s}:{self.col}",
            f"{indent}|",
            f"{line_s} | {self.source_line}",
            f"{indent}| {caret}^---",
            f"{indent}|",
            f"{indent}= expected {self.expected}",
        ])


class SemanticError(Exception):
    def __init__(self, message):
        self.message = message

    def format(self):
        return f"Error: {self.message}"


class Source:
    """Source position tracker."""

    def __init__(self, text):
        self.text = text
        self.pos = 0
        self.line = 1
        self.col = 1

    def eof(self):
        return self.pos >= len(self.text)

    def peek(self, offset=0):
        p = self.pos + offset
        return self.text[p] if p < len(self.text) else None

    def peek_str(self, n):
        return self.text[self.pos:self.pos + n]

    def advance(self):
        if self.pos >= len(self.text):
            return None
        ch = self.text[self.pos]
        self.pos += 1
        if ch == '\n':
            self.line += 1
            self.col = 1
        else:
            self.col += 1
        return ch

    def save(self):
        return (self.pos, self.line, self.col)

    def restore(self, state):
        self.pos, self.line, self.col = state

    def line_text(self, ln=None):
        if ln is None:
            ln = self.line
        lines = self.text.split('\n')
        if 1 <= ln <= len(lines):
            return lines[ln - 1]
        return ''

    def error(self, expected):
        return ParseError(self.line, self.col, self.line_text(), expected)

    def skip_ws(self):
        """Skip whitespace and comments."""
        while not self.eof():
            ch = self.peek()
            if ch in ' \t\r\n':
                self.advance()
            elif self.peek_str(2) == '//':
                while not self.eof() and self.peek() != '\n':
                    self.advance()
            else:
                break


def read_keyword(src, kw):
    """Consume keyword kw if present (not followed by identifier-continuation chars)."""
    n = len(kw)
    if src.peek_str(n) != kw:
        return False
    # Check character after keyword
    pos_after = src.pos + n
    if pos_after < len(src.text):
        next_ch = src.text[pos_after]
        if next_ch.isalpha() or next_ch == '_':
            return False
    for _ in kw:
        src.advance()
    return True


def read_identifier(src):
    """Read [a-zA-Z_]+ or return None."""
    if src.eof() or not (src.peek().isalpha() or src.peek() == '_'):
        return None
    result = []
    while not src.eof() and (src.peek().isalpha() or src.peek() == '_'):
        result.append(src.advance())
    return ''.join(result)


def read_integer(src):
    """Read integer or return None."""
    if src.eof() or not src.peek().isdigit():
        return None
    result = []
    while not src.eof() and src.peek().isdigit():
        result.append(src.advance())
    return int(''.join(result))


def read_string_literal(src):
    """Read "..." string. Raises ParseError if unterminated."""
    assert src.peek() == '"'
    start = (src.line, src.col, src.line_text())
    src.advance()  # consume opening "
    chars = []
    while not src.eof():
        ch = src.peek()
        if ch == '"':
            src.advance()
            return ''.join(chars)
        elif ch == '\\':
            src.advance()
            if src.eof():
                chars.append('\\')
                break
            next_ch = src.advance()
            if next_ch == '"':
                chars.append('"')
            else:
                chars.append('\\')
                chars.append(next_ch)
        else:
            chars.append(src.advance())
    # Unterminated
    raise ParseError(start[0], start[1], start[2], 'root')


def read_raw_literal(src):
    """Read `...` raw regex. Raises ParseError if invalid."""
    assert src.peek() == '`'
    start = (src.line, src.col, src.line_text())
    src.advance()  # consume opening `
    chars = []
    while not src.eof():
        ch = src.peek()
        if ch == '`':
            src.advance()
            return ''.join(chars)
        elif ch == '\\':
            # Backslash not allowed in raw
            raise ParseError(start[0], start[1], start[2], 'root')
        else:
            chars.append(src.advance())
    raise ParseError(start[0], start[1], start[2], 'root')


def read_symbol_name(src):
    """Read <name>. src should be at '<'."""
    assert src.peek() == '<'
    src.advance()  # consume <
    name_chars = []
    while not src.eof() and src.peek() != '>':
        name_chars.append(src.advance())
    if not src.eof():
        src.advance()  # consume >
    return ''.join(name_chars)


# Expected message constants
EXPECTED_ROOT = 'root'
EXPECTED_TOP_LEVEL = ('EOI, literal, raw, not, range, quantifier_quantity, '
                      'group_declaration, assertion_declaration, variable_declaration, '
                      'or variable_invocation')
EXPECTED_BLOCK_LEVEL = ('literal, raw, not, range, quantifier_quantity, '
                        'group_declaration, assertion_declaration, variable_declaration, '
                        'or variable_invocation')
EXPECTED_AFTER_OF = ('literal, raw, not, range, group_declaration, assertion_declaration, '
                     'variable_declaration, or variable_invocation')
EXPECTED_AMOUNT_OR_ASSERTION = 'amount or assertion_type'


def compile_source(text):
    """Compile Melody source to regex string."""
    src = Source(text)
    src.skip_ws()
    parts = []
    first = True
    while not src.eof():
        part = parse_root_stmt(src, first_stmt=first)
        parts.append(part)
        first = False
        src.skip_ws()
    return ''.join(parts)


def parse_root_stmt(src, first_stmt=False):
    """Parse one statement at the top level."""
    src.skip_ws()
    if src.eof():
        return ''

    line, col, line_text = src.line, src.col, src.line_text()

    # Expected message depends on context
    if first_stmt and line == 1 and col == 1:
        expected = EXPECTED_ROOT
    else:
        expected = EXPECTED_TOP_LEVEL

    return _parse_stmt(src, expected_on_fail=expected, in_block=False)


def _parse_stmt(src, expected_on_fail, in_block=False):
    """Parse a single statement (used at both top-level and inside blocks)."""
    src.skip_ws()
    if src.eof():
        raise src.error(expected_on_fail)

    line, col = src.line, src.col
    ch = src.peek()

    # Numeric: could be N of X, N to M of X, or char range N to M
    if ch and ch.isdigit():
        return parse_numeric_stmt(src)

    # Named quantifiers
    state = src.save()
    if read_keyword(src, 'some') and src.peek_str(3).startswith(' o') or False:
        src.restore(state)

    # Check for multi-word keywords first
    for kw, action in [
        ('some of', lambda: parse_quantifier_keyword(src, 'some of', '+')),
        ('any of', lambda: parse_quantifier_keyword(src, 'any of', '*')),
        ('option of', lambda: parse_quantifier_keyword(src, 'option of', '?')),
        ('over', lambda: parse_over_stmt(src)),
        ('not', lambda: parse_not_stmt(src)),
        ('match', lambda: parse_match_stmt(src)),
        ('either', lambda: parse_either_stmt(src)),
        ('capture', lambda: parse_capture_stmt(src)),
        ('ahead', lambda: parse_ahead_stmt(src, negative=False)),
        ('behind', lambda: parse_behind_stmt(src, negative=False)),
    ]:
        if src.peek_str(len(kw)) == kw:
            # Check word boundary for single-word keywords
            n = len(kw)
            pos_after = src.pos + n
            if pos_after < len(src.text):
                next_ch = src.text[pos_after]
                if kw[-1].isalpha() and (next_ch.isalpha() or next_ch == '_'):
                    continue  # Not a keyword boundary
            return action()

    # String literal
    if ch == '"':
        s = read_string_literal(src)
        src.skip_ws()
        if src.eof() or src.peek() != ';':
            raise src.error(EXPECTED_TOP_LEVEL if not in_block else EXPECTED_BLOCK_LEVEL)
        src.advance()  # consume ;
        return escape_regex(s)

    # Raw regex
    if ch == '`':
        r = read_raw_literal(src)
        src.skip_ws()
        if src.eof() or src.peek() != ';':
            raise src.error(EXPECTED_TOP_LEVEL if not in_block else EXPECTED_BLOCK_LEVEL)
        src.advance()
        return r

    # Symbol
    if ch == '<':
        sym = read_symbol_name(src)
        src.skip_ws()
        if src.eof() or src.peek() != ';':
            raise src.error(expected_on_fail)
        src.advance()
        if sym not in SYMBOLS:
            raise SemanticError("usage of an unrecognized symbol")
        return SYMBOLS[sym]

    # Character range: single_char 'to' single_char
    if ch and (ch.isalpha() or ch.isdigit()):
        state = src.save()
        start_ch = src.advance()
        src.skip_ws()
        if read_keyword(src, 'to'):
            src.skip_ws()
            if not src.eof() and (src.peek().isalpha() or src.peek().isdigit() or 
                                   (ord(src.peek()) >= 33 and ord(src.peek()) <= 126)):
                end_ch = src.advance()
                src.skip_ws()
                if src.eof() or src.peek() != ';':
                    raise src.error(expected_on_fail)
                src.advance()
                return f'[{start_ch}-{end_ch}]'
        src.restore(state)

    raise ParseError(line, col, src.line_text(line), expected_on_fail)


def parse_numeric_stmt(src):
    """Parse: N of X | N to M of X | N to M (char range)"""
    n = read_integer(src)
    src.skip_ws()
    line, col = src.line, src.col

    if read_keyword(src, 'of'):
        src.skip_ws()
        target = parse_quantifier_target(src)
        return apply_quantifier(target, f'{{{n}}}')

    if read_keyword(src, 'to'):
        src.skip_ws()
        if not src.eof() and src.peek().isdigit():
            m = read_integer(src)
            src.skip_ws()
            if read_keyword(src, 'of'):
                src.skip_ws()
                target = parse_quantifier_target(src)
                return apply_quantifier(target, f'{{{n},{m}}}')
            # No 'of' -> char range
            if src.eof() or src.peek() != ';':
                raise src.error(EXPECTED_TOP_LEVEL)
            src.advance()
            return f'[{n}-{m}]'
        # Single char
        if src.eof():
            raise src.error(EXPECTED_TOP_LEVEL)
        end_ch = src.advance()
        src.skip_ws()
        if src.eof() or src.peek() != ';':
            raise src.error(EXPECTED_TOP_LEVEL)
        src.advance()
        return f'[{n}-{end_ch}]'

    raise ParseError(line, col, src.line_text(line), EXPECTED_TOP_LEVEL)


def parse_quantifier_keyword(src, keyword, quantifier_char):
    """Parse: 'some of' X | 'any of' X | 'option of' X"""
    for ch in keyword:
        src.advance()
    src.skip_ws()
    target = parse_quantifier_target(src)
    return apply_quantifier(target, quantifier_char)


def parse_over_stmt(src):
    """Parse: 'over' N 'of' X"""
    for ch in 'over':
        src.advance()
    src.skip_ws()
    n = read_integer(src)
    if n is None:
        raise src.error(EXPECTED_TOP_LEVEL)
    src.skip_ws()
    if not read_keyword(src, 'of'):
        raise src.error(EXPECTED_TOP_LEVEL)
    src.skip_ws()
    target = parse_quantifier_target(src)
    return apply_quantifier(target, f'{{{n+1},}}')


