    """Read "..." string. Raises ParseError if unterminated."""
    assert src.peek() == '"'
    start = (src.line, src.col, src.line_text())
    src.advance()  # consume opening "
    chars = []
    while not src.eof():
        ch = src.peek()
        if ch == '"':
            src.advance()
            return ''.join(chars)
        elif ch == '\\':
            src.advance()
            if src.eof():
                chars.append('\\')
                break
            next_ch = src.advance()
            if next_ch == '"':
                chars.append('"')
            else:
                chars.append('\\')
                chars.append(next_ch)
