        pos_after = src.pos + 7
        if pos_after >= len(src.text) or not (src.text[pos_after].isalpha() or src.text[pos_after] == '_'):
            return parse_capture_stmt(src)

    # Assertions
    if src.peek_str(5) == 'ahead':
        pos_after = src.pos + 5
        if pos_after >= len(src.text) or not (src.text[pos_after].isalpha() or src.text[pos_after] == '_'):
            return parse_ahead_stmt(src, negative=False)

    if src.peek_str(6) == 'behind':
        pos_after = src.pos + 6
        if pos_after >= len(src.text) or not (src.text[pos_after].isalpha() or src.text[pos_after] == '_'):
            return parse_behind_stmt(src, negative=False)

    raise ParseError(line, col, src.line_text(line), EXPECTED_AFTER_OF)


def parse_not_class_target(src, error_line, error_col):
    """Parse the target after 'not' in a class negation context."""
    src.skip_ws()
    line, col = src.line, src.col
    ch = src.peek()

    if ch == '<':
        sym = read_symbol_name(src)
        src.skip_ws()
        if src.eof() or src.peek() != ';':
            raise ParseError(error_line, error_col, src.line_text(error_line), EXPECTED_AFTER_OF)
        src.advance()
        if sym not in SYMBOLS:
            raise SemanticError("usage of an unrecognized symbol")
        if sym in NOT_ERRORS:
            raise SemanticError(NOT_ERRORS[sym])
        if sym in NOT_SYMBOLS:
            return NOT_SYMBOLS[sym]
        raise SemanticError("usage of an unrecognized symbol")

    # Char range negation: not char to char
    if ch and (ch.isalpha() or ch.isdigit()):
        state = src.save()
        start_ch = src.advance()
        src.skip_ws()
        if read_keyword(src, 'to'):
            src.skip_ws()
            if not src.eof():
                end_ch = src.advance()
                src.skip_ws()
                if src.eof() or src.peek() != ';':
                    raise ParseError(error_line, error_col, src.line_text(error_line), EXPECTED_AFTER_OF)
                src.advance()
                return f'[^{start_ch}-{end_ch}]'
        src.restore(state)

    raise ParseError(error_line, error_col, src.line_text(error_line), EXPECTED_AMOUNT_OR_ASSERTION)


def parse_not_stmt(src):
    """Parse: 'not' (ahead/behind/symbol/range)"""
    for _ in 'not':
        src.advance()
    src.skip_ws()
    line, col = src.line, src.col
    ch = src.peek()

    # not ahead { ... }
    if src.peek_str(5) == 'ahead':
        pos_after = src.pos + 5
        if pos_after >= len(src.text) or not (src.text[pos_after].isalpha() or src.text[pos_after] == '_'):
            return parse_ahead_stmt(src, negative=True)

    # not behind { ... }
    if src.peek_str(6) == 'behind':
        pos_after = src.pos + 6
        if pos_after >= len(src.text) or not (src.text[pos_after].isalpha() or src.text[pos_after] == '_'):
            return parse_behind_stmt(src, negative=True)

    # not <symbol>
    if ch == '<':
        sym = read_symbol_name(src)
        src.skip_ws()
        if src.eof() or src.peek() != ';':
            raise ParseError(line, col, src.line_text(line), EXPECTED_AMOUNT_OR_ASSERTION)
        src.advance()
        if sym not in SYMBOLS:
            raise SemanticError("usage of an unrecognized symbol")
        if sym in NOT_ERRORS:
            raise SemanticError(NOT_ERRORS[sym])
        if sym in NOT_SYMBOLS:
            return NOT_SYMBOLS[sym]
        raise SemanticError("usage of an unrecognized symbol")

    # not char to char
    if ch and (ch.isalpha() or ch.isdigit()):
        state = src.save()
        start_ch = src.advance()
        src.skip_ws()
        if read_keyword(src, 'to'):
            src.skip_ws()
            if not src.eof():
                end_ch = src.advance()
                src.skip_ws()
                if src.eof() or src.peek() != ';':
                    raise ParseError(line, col, src.line_text(line), EXPECTED_AMOUNT_OR_ASSERTION)
                src.advance()
                return f'[^{start_ch}-{end_ch}]'
        src.restore(state)

    raise ParseError(line, col, src.line_text(line), EXPECTED_AMOUNT_OR_ASSERTION)


def parse_block_contents(src):
    """Parse the contents of a { ... } block."""
    parts = []
    src.skip_ws()

    BLOCK_EXPECTED = ('literal, raw, not, range, quantifier_quantity, '
                     'group_declaration, assertion_declaration, variable_declaration, '
                     'or variable_invocation')

    while not src.eof() and src.peek() != '}':
        part = parse_block_stmt(src)
        parts.append(part)
        src.skip_ws()
    return parts


def parse_block_stmt(src):
    """Parse one statement inside a block."""
    src.skip_ws()
    if src.eof():
        raise src.error(EXPECTED_BLOCK_LEVEL)

    line, col = src.line, src.col
    ch = src.peek()

    # Numeric quantifier or char range
    if ch and ch.isdigit():
        return parse_numeric_block_stmt(src)

    # Named quantifiers
    for kw, action in [
        ('some of', lambda: parse_quantifier_keyword(src, 'some of', '+')),
        ('any of', lambda: parse_quantifier_keyword(src, 'any of', '*')),
        ('option of', lambda: parse_quantifier_keyword(src, 'option of', '?')),
        ('over', lambda: parse_over_stmt(src)),
        ('not', lambda: parse_not_stmt(src)),
        ('match', lambda: parse_match_stmt(src)),
        ('either', lambda: parse_either_stmt(src)),
        ('capture', lambda: parse_capture_stmt(src)),
        ('ahead', lambda: parse_ahead_stmt(src, negative=False)),
        ('behind', lambda: parse_behind_stmt(src, negative=False)),
    ]:
        if src.peek_str(len(kw)) == kw:
            n = len(kw)
            pos_after = src.pos + n
            if pos_after < len(src.text):
                next_ch = src.text[pos_after]
                if kw[-1].isalpha() and (next_ch.isalpha() or next_ch == '_'):
                    continue
            return action()

    # String literal
    if ch == '"':
        s = read_string_literal(src)
        src.skip_ws()
        if src.eof() or src.peek() != ';':
            raise ParseError(line, col, src.line_text(line), EXPECTED_BLOCK_LEVEL)
        src.advance()
        return escape_regex(s)

    # Raw regex
    if ch == '`':
        r = read_raw_literal(src)
        src.skip_ws()
        if src.eof() or src.peek() != ';':
            raise ParseError(line, col, src.line_text(line), EXPECTED_BLOCK_LEVEL)
        src.advance()
        return r

    # Symbol
    if ch == '<':
        sym = read_symbol_name(src)
        src.skip_ws()
        if src.eof() or src.peek() != ';':
            raise ParseError(line, col, src.line_text(line), EXPECTED_BLOCK_LEVEL)
        src.advance()
        if sym not in SYMBOLS:
            raise SemanticError("usage of an unrecognized symbol")
        return SYMBOLS[sym]

    # Character range
    if ch and (ch.isalpha() or ch.isdigit()):
        state = src.save()
        start_ch = src.advance()
        src.skip_ws()
        if read_keyword(src, 'to'):
            src.skip_ws()
            if not src.eof():
                end_ch = src.advance()
                src.skip_ws()
                if src.eof() or src.peek() != ';':
                    raise ParseError(line, col, src.line_text(line), EXPECTED_BLOCK_LEVEL)
                src.advance()
                return f'[{start_ch}-{end_ch}]'
        src.restore(state)

    raise ParseError(line, col, src.line_text(line), EXPECTED_BLOCK_LEVEL)


def parse_numeric_block_stmt(src):
    """Parse N of X, N to M of X, or N to M (char range) inside a block."""
    n = read_integer(src)
    src.skip_ws()
    line, col = src.line, src.col

    if read_keyword(src, 'of'):
        src.skip_ws()
        target = parse_quantifier_target(src)
        return apply_quantifier(target, f'{{{n}}}')

    if read_keyword(src, 'to'):
        src.skip_ws()
        if not src.eof() and src.peek().isdigit():
            m = read_integer(src)
            src.skip_ws()
            if read_keyword(src, 'of'):
                src.skip_ws()
                target = parse_quantifier_target(src)
                return apply_quantifier(target, f'{{{n},{m}}}')
            # Char range
            if src.eof() or src.peek() != ';':
                raise ParseError(line, col, src.line_text(line), EXPECTED_BLOCK_LEVEL)
            src.advance()
            return f'[{n}-{m}]'
        if src.eof():
            raise ParseError(line, col, src.line_text(line), EXPECTED_BLOCK_LEVEL)
        end_ch = src.advance()
        src.skip_ws()
        if src.eof() or src.peek() != ';':
            raise ParseError(line, col, src.line_text(line), EXPECTED_BLOCK_LEVEL)
        src.advance()
        return f'[{n}-{end_ch}]'

    raise ParseError(line, col, src.line_text(line), EXPECTED_BLOCK_LEVEL)


def expect_char(src, expected_ch, expected_str=None):
    src.skip_ws()
    if src.eof() or src.peek() != expected_ch:
        raise src.error(expected_str or f"'{expected_ch}'")
    src.advance()


def parse_match_stmt(src):
    """Parse: 'match' '{' ... '}'"""
    for ch in 'match':
        src.advance()
    src.skip_ws()
    expect_char(src, '{')
    parts = parse_block_contents(src)
    src.skip_ws()
    expect_char(src, '}')
    return '(?:' + ''.join(parts) + ')'


def parse_either_stmt(src):
    """Parse: 'either' '{' ... '}'"""
    for ch in 'either':
        src.advance()
    src.skip_ws()
    expect_char(src, '{')
    parts = parse_block_contents(src)
    src.skip_ws()
    expect_char(src, '}')
    return '(?:' + '|'.join(parts) + ')'


def parse_capture_stmt(src):
    """Parse: 'capture' [name] '{' ... '}'"""
    for ch in 'capture':
        src.advance()
    src.skip_ws()
    line, col = src.line, src.col

    name = None
    if not src.eof() and src.peek() != '{':
        # Read the capture name
        name_chars = []

        # Read identifiers and whitespace
        first_ident = read_identifier(src)
        if first_ident is None:
            raise ParseError(line, col, src.line_text(line), 'block or identifier')
        name_chars.append(first_ident)

        while True:
            # Try to read more identifiers (possibly with whitespace)
            ws_start_pos = src.pos
            ws_start_line = src.line
            ws_start_col = src.col

            # Read whitespace
            ws = []
            while not src.eof() and src.peek() in ' \t\r\n':
                ws.append(src.advance())

            if src.eof() or src.peek() == '{':
                break  # End of name

            # Try to read another identifier
            ch_at = src.peek()
            if ch_at and ch_at.isalpha() or (ch_at and ch_at == '_'):
                ident = read_identifier(src)
                if ident:
                    name_chars.append(''.join(ws))
                    name_chars.append(ident)
                    continue

            # Not an identifier -> error
            raise ParseError(src.line, src.col, src.line_text(), 'block')

        name = ''.join(name_chars).strip()

    src.skip_ws()
    expect_char(src, '{')
    parts = parse_block_contents(src)
    src.skip_ws()
    expect_char(src, '}')
    inner = ''.join(parts)

    if name:
        return f'(?<{name}>{inner})'
    return f'({inner})'


def parse_ahead_stmt(src, negative=False):
    """Parse: 'ahead' '{' ... '}'"""
    for ch in 'ahead':
        src.advance()
    src.skip_ws()
    expect_char(src, '{')
    parts = parse_block_contents(src)
    src.skip_ws()
    expect_char(src, '}')
    inner = ''.join(parts)
    if negative:
        return f'(?!{inner})'
    return f'(?={inner})'


def parse_behind_stmt(src, negative=False):
    """Parse: 'behind' '{' ... '}'"""
    for ch in 'behind':
        src.advance()
    src.skip_ws()
    expect_char(src, '{')
    parts = parse_block_contents(src)
    src.skip_ws()
    expect_char(src, '}')
    inner = ''.join(parts)
    if negative:
        return f'(?<!{inner})'
    return f'(?<={inner})'


# ===== REPL =====

REPL_BANNER = f"Melody REPL v{VERSION}"

REPL_COMMANDS = """
Commands:

- :u, :undo - undo the latest line
- :r, :redo - redo the latest undo
- :c, :clear - clear all REPL history and previous input
- :s, :source - print all previously entered lines
- :e, :exit - exit the REPL
"""

def run_repl(no_color=False):
    """Run the interactive REPL."""
    if not sys.stdin.isatty() or not sys.stdout.isatty():
        msg = colorize("Error: repl argument supplied with piped input or output",
                      Color.RED, sys.stderr, no_color)
        print(msg, file=sys.stderr)
        return

    out = sys.stdout

    def pr(text, color=None):
        if color:
            text = colorize(text, color, out, no_color)
        print(text)

    def prompt():
        sys.stdout.write(colorize('~ ', Color.BLUE, out, no_color))
        sys.stdout.flush()

    # Welcome
    pr(REPL_BANNER, Color.GREEN)
    pr('')
    pr('Commands:', Color.GREEN)
    pr('')
    cmds = [
        (':u, :undo', 'undo the latest line'),
        (':r, :redo', 'redo the latest undo'),
        (':c, :clear', 'clear all REPL history and previous input'),
        (':s, :source', 'print all previously entered lines'),
        (':e, :exit', 'exit the REPL'),
    ]
    for cmd_name, cmd_desc in cmds:
        cn = colorize(cmd_name, Color.BLUE, out, no_color)
        cd = colorize(cmd_desc, Color.GREEN, out, no_color)
        print(f"- {cn} - {cd}")
    pr('')

    lines = []
    redo_stack = []

    def compile_lines(line_list):
        if not line_list:
            return ''
        return compile_source('\n'.join(line_list))

    def show_result(result_regex):
        pr(result_regex, Color.BLUE)

    def show_error(err):
        pr(err.format() if hasattr(err, 'format') else str(err), Color.RED)

    while True:
        prompt()
        try:
            line = input()
        except EOFError:
            break
        except KeyboardInterrupt:
            print()
            break

        cmd = line.strip()

        if cmd in (':e', ':exit'):
            pr('exit', Color.GREEN)
            break

        elif cmd in (':u', ':undo'):
            pr('undo', Color.GREEN)
            if lines:
                removed = lines.pop()
                redo_stack.append(removed)
                if lines:
                    try:
                        result = compile_lines(lines)
                        show_result(result)
                    except (ParseError, SemanticError) as e:
                        show_error(e)
            else:
                pr('nothing to undo', Color.GREEN)

        elif cmd in (':r', ':redo'):
            pr('redo', Color.GREEN)
            if redo_stack:
                restored = redo_stack.pop()
                lines.append(restored)
                try:
                    result = compile_lines(lines)
                    show_result(result)
                except (ParseError, SemanticError) as e:
                    show_error(e)
            else:
                pr('nothing to redo', Color.GREEN)

        elif cmd in (':c', ':clear'):
            pr('clear', Color.GREEN)
            lines = []
            redo_stack = []

        elif cmd in (':s', ':source'):
            pr('source', Color.GREEN)
            for i, l in enumerate(lines, 1):
                num = colorize_dim(str(i), out, no_color)
                code = colorize(l, Color.BLUE, out, no_color)
                print(f"{num} {code}")

        elif cmd.startswith(':'):
            pr(f'Error: unrecognized command "{cmd}"', Color.RED)

        else:
            new_lines = lines + [line]
            try:
                result = compile_lines(new_lines)
                lines = new_lines
                redo_stack = []
                show_result(result)
            except (ParseError, SemanticError) as e:
                show_error(e)


