def get_completions(shell):
    shell = shell.lower()
    if shell == 'bash':
        return get_completions_bash()
    elif shell == 'fish':
        return get_completions_fish()
    elif shell == 'zsh':
        return get_completions_zsh()
    elif shell == 'powershell':
        return get_completions_powershell()
    elif shell == 'elvish':
        return get_completions_elvish()
    return ''


def truncate_display(s, maxlen=10):
    if len(s) > maxlen:
        return s[:maxlen] + '...'
    return s


def do_test(regex_str, test_str, no_color=False):
    pattern = re.compile(regex_str)
    display = truncate_display(test_str)
    if pattern.search(test_str):
        result = colorize('matched', Color.GREEN, sys.stdout, no_color)
    else:
        result = colorize('did not match', Color.RED, sys.stdout, no_color)
    print(f"'{display}' {result}")


def do_test_file(regex_str, file_path, no_color=False):
    try:
        with open(file_path, 'r') as f:
            content = f.read()
    except (IOError, OSError):
        msg = f"Error: unable read file at path {file_path}"
        print(colorize(msg, Color.RED, sys.stderr, no_color), file=sys.stderr)
        return

    pattern = re.compile(regex_str)
    if pattern.search(content):
        result = colorize('matched', Color.GREEN, sys.stdout, no_color)
    else:
        result = colorize('did not match', Color.RED, sys.stdout, no_color)
    print(f"{file_path} {result}")


def print_error(msg, no_color=False):
    print(colorize(msg, Color.RED, sys.stderr, no_color), file=sys.stderr)


HELP_TEXT = """A CLI wrapping the Melody language compiler

Usage: melody [OPTIONS] [INPUT_FILE_PATH]

Arguments:
  [INPUT_FILE_PATH]  Read from a file
                     Use '-' and or pipe input to read from stdin

Options:
  -o, --output <OUTPUT_FILE_PATH>           Write to a file
  -n, --no-color                            Print output with no color
  -r, --repl                                Start the Melody REPL
      --generate-completions <completions>  Outputs completions for the selected shell
                                            To use, write the output to the appropriate location for your shell
  -t, --test <test>                         Test the compiled regex against a string
  -f, --test-file <test-file>               Test the compiled regex against the contents of a file
  -h, --help                                Print help
  -V, --version                             Print version"""


def main():
    # Manual argument parsing to match exact behavior
    args = sys.argv[1:]

    no_color = False
    repl = False
    output_file = None
    input_file = None
    generate_completions = None
    test_str = None
    test_file = None
    show_help = False
    show_version = False

    i = 0
    while i < len(args):
        arg = args[i]
        if arg in ('-n', '--no-color'):
            no_color = True
        elif arg in ('-r', '--repl'):
            repl = True
        elif arg in ('-h', '--help'):
            show_help = True
        elif arg in ('-V', '--version'):
            show_version = True
        elif arg in ('-o', '--output'):
            i += 1
            if i < len(args):
                output_file = args[i]
        elif arg.startswith('--output='):
            output_file = arg[9:]
        elif arg in ('-t', '--test'):
            i += 1
            if i < len(args):
                test_str = args[i]
        elif arg.startswith('--test='):
            test_str = arg[7:]
        elif arg in ('-f', '--test-file'):
            i += 1
            if i < len(args):
                test_file = args[i]
        elif arg.startswith('--test-file='):
            test_file = arg[12:]
        elif arg == '--generate-completions':
            i += 1
            if i < len(args):
                generate_completions = args[i]
        elif arg.startswith('--generate-completions='):
            generate_completions = arg[23:]
        elif not arg.startswith('-'):
            input_file = arg
        i += 1

    if show_help:
        print(HELP_TEXT)
        return

    if show_version:
        print(f"melody_cli {VERSION}")
        return

    if generate_completions is not None:
        completions = get_completions(generate_completions)
        sys.stdout.write(completions)
        return

    if repl:
        run_repl(no_color=no_color)
        return

    # Read input
    source = None
    if input_file is not None:
        if input_file == '-':
            source = sys.stdin.read()
        else:
            try:
                with open(input_file, 'r') as f:
                    source = f.read()
            except (IOError, OSError):
                print_error(f"Error: unable to read file at path {input_file}", no_color)
                sys.exit(65)
    elif not sys.stdin.isatty():
        source = sys.stdin.read()
    else:
        print(HELP_TEXT)
        return

    if source is None:
        return

    # Compile
    try:
        regex = compile_source(source)
    except ParseError as e:
        print_error(e.format(), no_color)
        sys.exit(65)
    except SemanticError as e:
        print_error(e.format(), no_color)
        sys.exit(65)

    # Handle tests
    if test_str is not None:
        do_test(regex, test_str, no_color)
        return

    if test_file is not None:
        do_test_file(regex, test_file, no_color)
        return

    # Output
    if output_file:
        with open(output_file, 'w') as f:
            f.write(regex)
    else:
        colored = colorize(regex, Color.BLUE, sys.stdout, no_color)
        print(colored)


