def main():
    args = sys.argv[1:]
    no_color = False
    repl = False
    output_file = None
    input_file = None
    gen_completions = None
    test_str = None
    test_file = None
    show_help = False
    show_version = False

    i = 0
    while i < len(args):
        a = args[i]
        if a in ('-n', '--no-color'):
            no_color = True
        elif a in ('-r', '--repl'):
            repl = True
        elif a in ('-h', '--help'):
            show_help = True
        elif a in ('-V', '--version'):
            show_version = True
        elif a in ('-o', '--output'):
            i += 1
            if i < len(args):
