#!/usr/bin/env python3
"""Melody language compiler - converts Melody to ECMAScript regex."""

import sys
import os
import re
import argparse

VERSION = "0.20.0"

class Color:
    GREEN = '\033[92m'
    BLUE = '\033[94m'
    RED = '\033[91m'
    DIM = '\033[2m'
    RESET = '\033[39m'
    RESET_ALL = '\033[0m'

def _has_color(stream):
    return hasattr(stream, 'isatty') and stream.isatty()

def colorize(text, color, stream, no_color=False):
    if no_color or not _has_color(stream):
        return text
    return f"{color}{text}{Color.RESET}"

def colorize_dim(text, stream, no_color=False):
    if no_color or not _has_color(stream):
        return text
    return f"{Color.DIM}{text}{Color.RESET_ALL}"

SYMBOLS = {
    'char': '.',
    'space': ' ',
    'whitespace': r'\s',
    'digit': r'\d',
    'word': r'\w',
    'newline': r'\n',
    'tab': r'\t',
    'return': r'\r',
    'feed': r'\f',
    'null': r'\0',
    'vertical': r'\v',
    'backspace': r'[\b]',
    'boundary': r'\b',
    'start': '^',
    'end': '$',
    'alphanumeric': '[a-zA-Z0-9]',
}

NOT_SYMBOLS = {
    'space': '[^ ]',
    'whitespace': r'\S',
    'digit': r'\D',
    'word': r'\W',
    'newline': r'[^\n]',
    'tab': r'[^\t]',
    'return': r'[^\r]',
    'feed': r'[^\f]',
    'null': r'[^\0]',
    'vertical': r'[^\v]',
    'backspace': r'[^\b]',
    'boundary': r'\B',
    'alphanumeric': '[^a-zA-Z0-9]',
}

NOT_ERRORS = {
    'char': 'negative char not allowed',
    'start': 'negative start not allowed',
    'end': 'negative end not allowed',
}

REGEX_SPECIAL = frozenset(r'\.+*?[]{}()|^$')

def escape_regex(s):
    return ''.join('\\' + c if c in REGEX_SPECIAL else c for c in s)

def is_single_atom(s):
    if not s:
        return True
    if len(s) == 1:
        return s not in '+*?|.^$'
    if len(s) == 2 and s[0] == '\\':
        return True
    if s[0] == '[' and s[-1] == ']':
        # Check it's balanced
        depth = 0
        for i, c in enumerate(s):
            if c == '[':
                depth += 1
            elif c == ']':
                depth -= 1
            if depth == 0:
                return i == len(s) - 1
        return False
    if s[0] == '(' and s[-1] == ')':
        depth = 0
        for i, c in enumerate(s):
            if c == '(':
                depth += 1
            elif c == ')':
                depth -= 1
            if depth == 0:
                return i == len(s) - 1
        return False
    return False

def apply_quantifier(inner, q):
    if is_single_atom(inner):
        return inner + q
    return f'(?:{inner}){q}'


class ParseError(Exception):
    def __init__(self, line, col, source_line, expected):
        self.line = line
        self.col = col
        self.source_line = source_line
        self.expected = expected

    def format(self):
        s = str(self.line)
        n = len(s)
        indent = ' ' * (n + 1)
        caret = ' ' * (self.col - 1)
        return '\n'.join([
            f"Error: {' ' * n}--> {s}:{self.col}",
            f"{indent}|",
            f"{s} | {self.source_line}",
            f"{indent}| {caret}^---",
            f"{indent}|",
            f"{indent}= expected {self.expected}",
        ])


class SemanticError(Exception):
    def __init__(self, message):
        self.message = message

    def format(self):
        return f"Error: {self.message}"


class Src:
    def __init__(self, text):
        self.text = text
        self.pos = 0
        self.line = 1
        self.col = 1

    def eof(self):
        return self.pos >= len(self.text)

    def peek(self, off=0):
        p = self.pos + off
        return self.text[p] if p < len(self.text) else None

    def peeks(self, n):
        return self.text[self.pos:self.pos + n]

    def adv(self):
        if self.pos >= len(self.text):
            return None
        c = self.text[self.pos]
        self.pos += 1
        if c == '\n':
            self.line += 1
            self.col = 1
        else:
            self.col += 1
        return c

    def save(self):
        return (self.pos, self.line, self.col)

    def restore(self, st):
        self.pos, self.line, self.col = st

    def line_text(self, ln=None):
        if ln is None:
            ln = self.line
        lines = self.text.split('\n')
        return lines[ln - 1] if 1 <= ln <= len(lines) else ''

    def err(self, expected):
        return ParseError(self.line, self.col, self.line_text(), expected)

    def skip_ws(self):
        while not self.eof():
            c = self.peek()
            if c in ' \t\r\n':
                self.adv()
            elif self.peeks(2) == '//':
                while not self.eof() and self.peek() != '\n':
                    self.adv()
            else:
                break


# Valid range chars (non-space printable, excl " and `)
def is_range_char(c):
    return c is not None and 33 <= ord(c) <= 126 and c not in ('"', '`')

# Valid single char for "not X;" context
# Works: [a-zA-Z0-9] + [!#$%&*@\^_]
NOT_CLASS_CHARS = frozenset('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!#$%&*@\\^_')

def is_not_class_char(c):
    return c in NOT_CLASS_CHARS


def read_kw(src, kw):
    """Consume kw if it's a complete keyword (not part of longer identifier)."""
    n = len(kw)
    if src.peeks(n) != kw:
        return False
    pos_after = src.pos + n
    if pos_after < len(src.text):
        nc = src.text[pos_after]
        if kw[-1].isalpha() and (nc.isalpha() or nc == '_'):
            return False
    for _ in kw:
        src.adv()
    return True


def read_ident(src):
    """Read [a-zA-Z_]+ or None."""
    if src.eof() or not (src.peek().isalpha() or src.peek() == '_'):
        return None
    r = []
    while not src.eof() and (src.peek().isalpha() or src.peek() == '_'):
        r.append(src.adv())
    return ''.join(r)


def read_int(src):
    """Read integer or None."""
    if src.eof() or not src.peek().isdigit():
        return None
    r = []
    while not src.eof() and src.peek().isdigit():
        r.append(src.adv())
    return int(''.join(r))


def read_str(src):
    """Read "..." literal. Returns string content."""
    sl, sc, slt = src.line, src.col, src.line_text()
    assert src.peek() == '"'
    src.adv()
    r = []
    while not src.eof():
        c = src.peek()
        if c == '"':
            src.adv()
            return ''.join(r)
        elif c == '\\':
            src.adv()
            if src.eof():
                r.append('\\')
                break
            nc = src.adv()
            r.append('"' if nc == '"' else '\\' + nc)
        else:
            r.append(src.adv())
    raise ParseError(sl, sc, slt, 'root')


def read_raw(src):
    """Read `...` literal. Returns regex content."""
    sl, sc, slt = src.line, src.col, src.line_text()
    assert src.peek() == '`'
    src.adv()
    r = []
    while not src.eof():
        c = src.peek()
        if c == '`':
            src.adv()
            return ''.join(r)
        elif c == '\\':
            raise ParseError(sl, sc, slt, 'root')
        else:
            r.append(src.adv())
    raise ParseError(sl, sc, slt, 'root')


def read_sym(src):
    """Read <name>. Returns name string."""
    assert src.peek() == '<'
    src.adv()
    r = []
    while not src.eof() and src.peek() != '>':
        r.append(src.adv())
    if not src.eof():
        src.adv()
    return ''.join(r)


def expect_semi(src, stmt_line, stmt_col, stmt_lt, expected):
    """Expect ';' - raise error at STATEMENT start position if missing."""
    src.skip_ws()
    if src.eof() or src.peek() != ';':
        raise ParseError(stmt_line, stmt_col, stmt_lt, expected)
    src.adv()


# ======== Parser ========

# Expected message strings
E_ROOT = 'root'
E_TOP = ('EOI, literal, raw, not, range, quantifier_quantity, group_declaration, '
         'assertion_declaration, variable_declaration, or variable_invocation')
E_TOP_SHORT = ('EOI, quantifier_quantity, group_declaration, assertion_declaration, or variable_declaration')
E_BLOCK = ('literal, raw, not, range, quantifier_quantity, group_declaration, '
           'assertion_declaration, variable_declaration, or variable_invocation')
E_BLOCK_SHORT = ('quantifier_quantity, group_declaration, assertion_declaration, or variable_declaration')
E_AFTER_OF = ('literal, raw, not, range, group_declaration, assertion_declaration, '
              'variable_declaration, or variable_invocation')
E_AFTER_OF_SHORT = ('group_declaration, assertion_declaration, or variable_declaration')
E_NOT = 'amount or assertion_type'
E_ASSERTION = 'assertion_type'


def compile_source(text):
    src = Src(text)
    src.skip_ws()
    parts = []
    n_stmts = 0
    while not src.eof():
        sl, sc = src.line, src.col
        slt = src.line_text(sl)

        if n_stmts == 0 and sl == 1 and sc == 1:
            # First statement, at root - wrap errors as "root"
            try:
                part = parse_stmt_top(src, first=True)
            except ParseError:
                raise ParseError(sl, sc, slt, E_ROOT)
            except SemanticError:
                raise
        else:
            part = parse_stmt_top(src, first=False)

        parts.append(part)
        n_stmts += 1
        src.skip_ws()
    return ''.join(parts)


def parse_stmt_top(src, first=False):
    """Parse one top-level statement."""
    src.skip_ws()
    if src.eof():
        return ''

    sl, sc = src.line, src.col
    slt = src.line_text(sl)

    # The error if nothing matches (for top-level after first)
    err_expected = E_TOP if not first else E_ROOT

    return _parse_stmt(src, sl, sc, slt, err_expected, in_block=False)


def _parse_stmt(src, stmt_l, stmt_c, stmt_lt, err_expected, in_block=False):
    """Parse one statement with known start position."""
    src.skip_ws()
    if src.eof():
        raise ParseError(stmt_l, stmt_c, stmt_lt, err_expected)

    c = src.peek()

    # Numeric
    if c and c.isdigit():
        return _parse_numeric(src, stmt_l, stmt_c, stmt_lt, err_expected, in_block)

    # Keyword dispatching
    for kw in ['some of', 'any of', 'option of', 'over', 'not',
               'match', 'either', 'capture', 'ahead', 'behind']:
        n = len(kw)
        if src.peeks(n) == kw:
            pa = src.pos + n
            if kw[-1].isalpha() and pa < len(src.text) and (src.text[pa].isalpha() or src.text[pa] == '_'):
                continue
            if kw == 'some of':
                for _ in kw: src.adv()
                src.skip_ws()
                return apply_quantifier(parse_qof_target(src, stmt_l, stmt_c, stmt_lt), '+')
            elif kw == 'any of':
                for _ in kw: src.adv()
                src.skip_ws()
                return apply_quantifier(parse_qof_target(src, stmt_l, stmt_c, stmt_lt), '*')
            elif kw == 'option of':
                for _ in kw: src.adv()
                src.skip_ws()
                return apply_quantifier(parse_qof_target(src, stmt_l, stmt_c, stmt_lt), '?')
            elif kw == 'over':
                return _parse_over(src, stmt_l, stmt_c, stmt_lt)
            elif kw == 'not':
                return _parse_not(src)
            elif kw == 'match':
                return _parse_match(src)
            elif kw == 'either':
                return _parse_either(src)
            elif kw == 'capture':
                return _parse_capture(src)
            elif kw == 'ahead':
                return _parse_ahead(src, False)
            elif kw == 'behind':
                return _parse_behind(src, False)

    # String literal
    if c == '"':
        s = read_str(src)
        expect_semi(src, stmt_l, stmt_c, stmt_lt, err_expected)
        return escape_regex(s)

    # Raw
    if c == '`':
        r = read_raw(src)
        expect_semi(src, stmt_l, stmt_c, stmt_lt, err_expected)
        return r

    # Symbol
    if c == '<':
        sym = read_sym(src)
        expect_semi(src, stmt_l, stmt_c, stmt_lt, err_expected)
        if sym not in SYMBOLS:
            raise SemanticError("usage of an unrecognized symbol")
        return SYMBOLS[sym]

    # Character range: char to char
    if is_range_char(c):
        st = src.save()
        sc2 = src.adv()
        src.skip_ws()
        if read_kw(src, 'to'):
            src.skip_ws()
            if not src.eof() and is_range_char(src.peek()):
                ec = src.adv()
                expect_semi(src, stmt_l, stmt_c, stmt_lt, err_expected)
                return f'[{sc2}-{ec}]'
        src.restore(st)

    raise ParseError(stmt_l, stmt_c, stmt_lt, err_expected)


def _parse_numeric(src, stmt_l, stmt_c, stmt_lt, err_expected, in_block=False):
    n = read_int(src)
    src.skip_ws()

    if read_kw(src, 'of'):
        src.skip_ws()
        # Save position for quantifier target
        tl, tc = src.line, src.col
        tlt = src.line_text(tl)
        target = parse_qof_target(src, tl, tc, tlt)
        return apply_quantifier(target, f'{{{n}}}')

    if read_kw(src, 'to'):
        src.skip_ws()
        if not src.eof() and src.peek().isdigit():
            m = read_int(src)
            src.skip_ws()
            if read_kw(src, 'of'):
                src.skip_ws()
                tl, tc = src.line, src.col
                tlt = src.line_text(tl)
                target = parse_qof_target(src, tl, tc, tlt)
                return apply_quantifier(target, f'{{{n},{m}}}')
            # Char range
            expect_semi(src, stmt_l, stmt_c, stmt_lt, err_expected)
            return f'[{n}-{m}]'
        # Single char after N to
        if src.eof():
            raise ParseError(stmt_l, stmt_c, stmt_lt, err_expected)
        ec = src.adv()
        expect_semi(src, stmt_l, stmt_c, stmt_lt, err_expected)
        return f'[{n}-{ec}]'

    raise ParseError(stmt_l, stmt_c, stmt_lt, err_expected)


def _parse_over(src, stmt_l, stmt_c, stmt_lt):
    read_kw(src, 'over')
    src.skip_ws()
    n = read_int(src)
    if n is None:
        raise ParseError(stmt_l, stmt_c, stmt_lt, E_TOP)
    src.skip_ws()
    if not read_kw(src, 'of'):
        raise ParseError(stmt_l, stmt_c, stmt_lt, E_TOP)
    src.skip_ws()
    tl, tc = src.line, src.col
    tlt = src.line_text(tl)
    target = parse_qof_target(src, tl, tc, tlt)
    return apply_quantifier(target, f'{{{n+1},}}')


def parse_qof_target(src, stmt_l, stmt_c, stmt_lt):
    """Parse the target of 'X of': literal, raw, symbol, not, range, or group."""
    src.skip_ws()
    if src.eof():
        raise ParseError(stmt_l, stmt_c, stmt_lt, E_AFTER_OF)

    c = src.peek()

    # Literal
    if c == '"':
        s = read_str(src)
        expect_semi(src, stmt_l, stmt_c, stmt_lt, E_AFTER_OF_SHORT)
        return escape_regex(s)

    # Raw
    if c == '`':
        r = read_raw(src)
        expect_semi(src, stmt_l, stmt_c, stmt_lt, E_AFTER_OF_SHORT)
        return r

    # Symbol
    if c == '<':
        sym = read_sym(src)
        expect_semi(src, stmt_l, stmt_c, stmt_lt, E_AFTER_OF)
        if sym not in SYMBOLS:
            raise SemanticError("usage of an unrecognized symbol")
        return SYMBOLS[sym]

    # 'not'
    if src.peeks(3) == 'not':
        pa = src.pos + 3
        if pa >= len(src.text) or not (src.text[pa].isalpha() or src.text[pa] == '_'):
            return _parse_not(src)

    # Char range: char to char
    if is_range_char(c):
        st = src.save()
        sc2 = src.adv()
        src.skip_ws()
        if read_kw(src, 'to'):
            src.skip_ws()
            if not src.eof() and is_range_char(src.peek()):
                ec = src.adv()
                expect_semi(src, stmt_l, stmt_c, stmt_lt, 
                           'amount, literal, not, group_declaration, assertion_declaration, or variable_declaration')
                return f'[{sc2}-{ec}]'
        src.restore(st)

    # Groups
    for kw, fn in [('match', _parse_match), ('either', _parse_either),
                   ('capture', _parse_capture), ('ahead', lambda s: _parse_ahead(s, False)),
                   ('behind', lambda s: _parse_behind(s, False))]:
        n = len(kw)
        if src.peeks(n) == kw:
            pa = src.pos + n
            if kw[-1].isalpha() and pa < len(src.text) and (src.text[pa].isalpha() or src.text[pa] == '_'):
                continue
            return fn(src)

    raise ParseError(stmt_l, stmt_c, stmt_lt, E_AFTER_OF)


def _parse_not(src):
    """Parse 'not ...'"""
    read_kw(src, 'not')
    src.skip_ws()
    nl, nc = src.line, src.col
    nlt = src.line_text(nl)
    c = src.peek()

    # not ahead/behind
    for kw, fn in [('ahead', lambda s: _parse_ahead(s, True)),
                   ('behind', lambda s: _parse_behind(s, True))]:
        n = len(kw)
        if src.peeks(n) == kw:
            pa = src.pos + n
            if kw[-1].isalpha() and pa < len(src.text) and (src.text[pa].isalpha() or src.text[pa] == '_'):
                continue
