            raise SemanticError("usage of an unrecognized symbol")
        if sym in NOT_ERRORS:
            raise SemanticError(NOT_ERRORS[sym])
        if sym in NOT_SYMBOLS:
            return NOT_SYMBOLS[sym]
        raise SemanticError("usage of an unrecognized symbol")

