    return '(?:' + ''.join(parts) + ')'


def _parse_either(src):
    read_kw(src, 'either')
    src.skip_ws()
    if src.eof() or src.peek() != '{':
        raise src.err("'{'")
    src.adv()
    parts = _parse_block_contents(src)
    src.skip_ws()
