      --generate-completions <completions>  Outputs completions for the selected shell
                                            To use, write the output to the appropriate location for your shell
  -t, --test <test>                         Test the compiled regex against a string
  -f, --test-file <test-file>               Test the compiled regex against the contents of a file
  -h, --help                                Print help
  -V, --version                             Print version"""


def main():
    args = sys.argv[1:]
    no_color = False
    repl = False
    output_file = None
    input_file = None
    gen_completions = None
    test_str = None
    test_file = None
    show_help = False
    show_version = False

    i = 0
    while i < len(args):
        a = args[i]
        if a in ('-n', '--no-color'):
            no_color = True
        elif a in ('-r', '--repl'):
            repl = True
        elif a in ('-h', '--help'):
            show_help = True
        elif a in ('-V', '--version'):
            show_version = True
        elif a in ('-o', '--output'):
            i += 1
            if i < len(args):
                output_file = args[i]
        elif a.startswith('--output='):
            output_file = a[9:]
        elif a in ('-t', '--test'):
            i += 1
            if i < len(args):
                test_str = args[i]
        elif a.startswith('--test='):
            test_str = a[7:]
        elif a in ('-f', '--test-file'):
            i += 1
            if i < len(args):
                test_file = args[i]
        elif a.startswith('--test-file='):
            test_file = a[12:]
        elif a == '--generate-completions':
            i += 1
            if i < len(args):
                gen_completions = args[i]
        elif a.startswith('--generate-completions='):
            gen_completions = a[23:]
        elif not a.startswith('-'):
            input_file = a
        i += 1

    if show_help:
        print(HELP_TEXT)
        return

    if show_version:
        print(f"melody_cli {VERSION}")
        return

    if gen_completions is not None:
        sys.stdout.write(get_completions(gen_completions))
        return

    if repl:
        run_repl(no_color=no_color)
