    try:
        regex = compile_source(source)
    except ParseError as e:
        print_error(e.format(), no_color)
        sys.exit(65)
    except SemanticError as e:
        print_error(e.format(), no_color)
        sys.exit(65)

    if test_str is not None:
        do_test(regex, test_str, no_color)
        return

    if test_file is not None:
        do_test_file(regex, test_file, no_color)
        return

    if output_file:
        with open(output_file, 'w') as f:
            f.write(regex)
    else:
        print(colorize(regex, Color.BLUE, sys.stdout, no_color))


