def read_raw(src):
    """Read `...` literal. Returns regex content."""
    sl, sc, slt = src.line, src.col, src.line_text()
    assert src.peek() == '`'
    src.adv()
    r = []
    while not src.eof():
        c = src.peek()
        if c == '`':
            src.adv()
            return ''.join(r)
        elif c == '\\':
            raise ParseError(sl, sc, slt, 'root')
        else:
            r.append(src.adv())
    raise ParseError(sl, sc, slt, 'root')


def read_sym(src):
    """Read <name>. Returns name string."""
    assert src.peek() == '<'
    src.adv()
    r = []
    while not src.eof() and src.peek() != '>':
        r.append(src.adv())
    if not src.eof():
