def main():
    args = sys.argv[1:]
    no_color = False
    repl = False
    output_file = None
    input_file = None
    gen_completions = None
    test_str = None
    test_file = None
    show_help = False
    show_version = False

    i = 0
    while i < len(args):
        a = args[i]
        if a in ('-n', '--no-color'):
            no_color = True
        elif a in ('-r', '--repl'):
            repl = True
        elif a in ('-h', '--help'):
            show_help = True
        elif a in ('-V', '--version'):
            show_version = True
        elif a in ('-o', '--output'):
            i += 1
            if i < len(args):
                output_file = args[i]
        elif a.startswith('--output='):
            output_file = a[9:]
        elif a in ('-t', '--test'):
            i += 1
            if i < len(args):
                test_str = args[i]
        elif a.startswith('--test='):
            test_str = a[7:]
        elif a in ('-f', '--test-file'):
            i += 1
            if i < len(args):
                test_file = args[i]
        elif a.startswith('--test-file='):
            test_file = a[12:]
        elif a == '--generate-completions':
            i += 1
            if i < len(args):
                gen_completions = args[i]
        elif a.startswith('--generate-completions='):
            gen_completions = a[23:]
        elif not a.startswith('-'):
            input_file = a
        i += 1

    if show_help:
        print(HELP_TEXT)
        return

    if show_version:
        print(f"melody_cli {VERSION}")
        return

    if gen_completions is not None:
        sys.stdout.write(get_completions(gen_completions))
        return

    if repl:
        run_repl(no_color=no_color)
        return

    # Read input
    source = None
    if input_file is not None:
        if input_file == '-':
            source = sys.stdin.read()
        else:
            try:
                with open(input_file, 'r') as f:
                    source = f.read()
            except (IOError, OSError):
                print_error(f"Error: unable to read file at path {input_file}", no_color)
                sys.exit(65)
    elif not sys.stdin.isatty():
        source = sys.stdin.read()
    else:
        print(HELP_TEXT)
        return

    if source is None:
        return

    try:
        regex = compile_source(source)
    except ParseError as e:
        print_error(e.format(), no_color)
        sys.exit(65)
    except SemanticError as e:
        print_error(e.format(), no_color)
        sys.exit(65)

    if test_str is not None:
        do_test(regex, test_str, no_color)
        return

    if test_file is not None:
        do_test_file(regex, test_file, no_color)
        return

    if output_file:
        with open(output_file, 'w') as f:
            f.write(regex)
    else:
        print(colorize(regex, Color.BLUE, sys.stdout, no_color))


if __name__ == '__main__':
    main()
